fn render_vm_status(
    state_dir: Option<&str>,
    manifest_path: Option<&str>,
    helper_path: Option<&str>,
    json: bool,
) -> String {
    let config = macos_vm_config(state_dir, None, None);
    let default_manifest_path = default_macos_vm_manifest_path(&config);
    let provisioning_path = default_macos_vm_guest_provisioning_path(&config);
    let shutdown_path = default_macos_vm_runtime_shutdown_path(&config);
    let (manifest, manifest_load_reason, effective_manifest_path) =
        load_macos_vm_manifest(manifest_path, &default_manifest_path);
    let provisioning = load_macos_vm_guest_provisioning(&provisioning_path, helper_path);
    let shutdown = load_macos_vm_runtime_shutdown(&shutdown_path);
    let status = status_from_config(&config, HostPlatform::current(), manifest.as_ref());
    let helper = run_macos_vm_helper(
        helper_path,
        "status",
        &[
            "--state-dir".to_string(),
            config.state_dir.display().to_string(),
            "--json".to_string(),
        ],
    );
    let effective_reason_codes = effective_vm_reason_codes(&status, &helper);
    let lifecycle_reason_codes = vm_lifecycle_reason_codes(&status, &helper);
    let guest_reprovision_command = guest_reprovision_command(
        helper.configured_path.as_deref(),
        &config.state_dir,
        &provisioning,
    );
    if json {
        return render_vm_status_json(VmStatusJsonRenderArgs {
            status: &status,
            manifest_path: &effective_manifest_path,
            manifest_load_reason: manifest_load_reason.as_deref(),
            provisioning: &provisioning,
            shutdown: &shutdown,
            guest_reprovision_command: guest_reprovision_command.as_deref(),
            helper: &helper,
            effective_reason_codes: &effective_reason_codes,
            lifecycle_reason_codes: &lifecycle_reason_codes,
        });
    }
    let mut output = format!(
        "whoathere vm status\nschema_version={}\nrelease_target={}\ntarget_arch={}\nvm_boundary={}\nnetwork_model={}\nsync_policy={}\nstate_dir={}\nhost_os={}\nhost_arch={}\nmemory_mib={}\ndisk_gib={}\nauto_suspend_minutes={}\nstate_dir_exists={}\nmanifest_path={}\nmanifest_present={}\nmanifest_valid={}\nhelper_ready_marker_present={}\nimage_ready_marker_present={}\nlifecycle_ready={}\nruntime_ready={}\nready={}\nreason_codes={:?}\nlifecycle_reason_codes={:?}\n{}\n{}\nguest_reprovision_required={}\nguest_reprovision_admin_required={}\nguest_reprovision_operator_action={}\nguest_reprovision_command={}\n{}",
        status.schema_version,
        status.release_target,
        status.target_arch,
        status.vm_boundary,
        status.network_model,
        status.sync_policy,
        status.state_dir.display(),
        status.host.os,
        status.host.arch,
        status.memory_mib,
        status.disk_gib,
        status.auto_suspend_minutes,
        status.state_dir_exists,
        effective_manifest_path,
        status.manifest_present,
        status.manifest_valid,
        status.helper_ready_marker_present,
        status.image_ready_marker_present,
        lifecycle_reason_codes.is_empty(),
        effective_reason_codes.is_empty(),
        effective_reason_codes.is_empty(),
        effective_reason_codes,
        lifecycle_reason_codes,
        provisioning.render_text(),
        render_runtime_shutdown_text(&shutdown),
        guest_reprovision_required(&provisioning),
        guest_reprovision_admin_required(&provisioning),
        guest_reprovision_operator_action(&provisioning, guest_reprovision_command.as_deref()),
        guest_reprovision_command.as_deref().unwrap_or("none"),
        helper.render_summary_text()
    );
    if let Some(reason) = manifest_load_reason {
        output.push_str(&format!("\nmanifest_load_reason={reason}"));
    }
    output
}

struct VmInitRenderArgs<'a> {
    state_dir: Option<&'a str>,
    manifest_path: Option<&'a str>,
    helper_path: Option<&'a str>,
    image_path: Option<&'a str>,
    restore_image_path: Option<&'a str>,
    fetch_latest_restore_image: bool,
    memory_mib: Option<u64>,
    disk_gib: Option<u64>,
    execute: bool,
}

fn render_vm_init(args: VmInitRenderArgs<'_>) -> String {
    let config = macos_vm_config(args.state_dir, args.memory_mib, args.disk_gib);
    let default_manifest_path = default_macos_vm_manifest_path(&config);
    let (manifest, manifest_load_reason, effective_manifest_path) =
        load_macos_vm_manifest(args.manifest_path, &default_manifest_path);
    let status = status_from_config(&config, HostPlatform::current(), manifest.as_ref());
    let mut reason_codes = status.reason_codes.clone();
    if !args.execute {
        reason_codes.push("macos_vm_init_execute_required_for_mutation".to_string());
    }
    reason_codes.sort();
    reason_codes.dedup();

    let helper = if args.execute {
        let mut helper_args = vec![
            "--state-dir".to_string(),
            config.state_dir.display().to_string(),
            "--memory-mib".to_string(),
            config.memory_mib.to_string(),
            "--disk-gib".to_string(),
            config.disk_gib.to_string(),
            "--execute".to_string(),
            "--json".to_string(),
        ];
        if let Some(image_path) = args.image_path {
            helper_args.push("--image".to_string());
            helper_args.push(image_path.to_string());
        }
        if let Some(restore_image_path) = args.restore_image_path {
            helper_args.push("--restore-image".to_string());
            helper_args.push(restore_image_path.to_string());
        }
        if args.fetch_latest_restore_image {
            helper_args.push("--fetch-latest-restore-image".to_string());
        }
        run_macos_vm_helper(args.helper_path, "init", &helper_args)
    } else {
        run_macos_vm_helper(
            args.helper_path,
            "init",
            &[
                "--state-dir".to_string(),
                config.state_dir.display().to_string(),
                "--memory-mib".to_string(),
                config.memory_mib.to_string(),
                "--disk-gib".to_string(),
                config.disk_gib.to_string(),
                "--json".to_string(),
            ],
        )
    };
    let final_exit_code = if args.execute {
        helper.exit_code.unwrap_or_else(|| ExitCode::Misuse.code())
    } else {
        ExitCode::Allow.code()
    };

    let mut output = format!(
        "whoathere vm init\nschema_version={}\nrelease_target={}\ntarget_arch={}\nvm_boundary={}\nnetwork_model={}\nsync_policy={}\nmutation={}\ndirect_cli_state_mutation=false\nstate_dir={}\nmanifest_path={}\nhelper_required_for_execute={}\nimage_path={}\nrestore_image_path={}\nfetch_latest_restore_image={}\nmemory_mib={}\ndisk_gib={}\nnative_memory_mib={}\nready=false\nreason_codes={:?}\n{}",
        whoathere_macos_vm::STATUS_SCHEMA_VERSION,
        RELEASE_TARGET,
        TARGET_ARCH,
        VM_BOUNDARY,
        NETWORK_MODEL,
        SYNC_POLICY,
        args.execute,
        config.state_dir.display(),
        effective_manifest_path,
        args.execute,
        redacted_option_scalar(args.image_path),
        redacted_option_scalar(args.restore_image_path),
        args.fetch_latest_restore_image,
        config.memory_mib,
        config.disk_gib,
        DEFAULT_NATIVE_MEMORY_MIB,
        reason_codes,
        helper.render_text()
    );
    if let Some(reason) = manifest_load_reason {
        output.push_str(&format!("\nmanifest_load_reason={reason}"));
    }
    output.push_str(&format!("\nexit_code={final_exit_code}"));
    output
}

fn render_vm_reprovision(
    state_dir: Option<&str>,
    helper_path: Option<&str>,
    preflight: bool,
    execute: bool,
) -> String {
    let config = macos_vm_config(state_dir, None, None);
    let script_path = match resolve_guest_reprovision_script_path(helper_path) {
        Ok(path) => path,
        Err(reason_code) => {
            return format!(
                "whoathere vm reprovision\nrelease_target={}\nstate_dir={}\nmutation=false\npreflight_requested={preflight}\nexecute_requested={execute}\nstatus=error\nreason_code={reason_code}\nexit_code={}",
                RELEASE_TARGET,
                config.state_dir.display(),
                ExitCode::Misuse.code()
            );
        }
    };
    let reprovision_command = reprovision_command_for_script(&script_path, &config.state_dir);
    if preflight && execute {
        return format!(
            "whoathere vm reprovision\nrelease_target={}\nstate_dir={}\nmutation=false\npreflight_requested=true\nexecute_requested=true\nstatus=error\nreason_code=reprovision_preflight_and_execute_conflict\nreprovision_command={}\nexit_code={}",
            RELEASE_TARGET,
            config.state_dir.display(),
            reprovision_command,
            ExitCode::Misuse.code()
        );
    }
    if !preflight && !execute {
        return format!(
            "whoathere vm reprovision\nrelease_target={}\nstate_dir={}\nmutation=false\npreflight_requested=false\nexecute_requested=false\nstatus=dry_run\nadmin_required_for_execute=true\nscript_path={}\nreprovision_command={}\nexplanation=run with --preflight to verify local inputs or run the reprovision_command in an interactive admin terminal\nexit_code={}",
            RELEASE_TARGET,
            config.state_dir.display(),
            redacted_scalar(&script_path.display().to_string()),
            reprovision_command,
            ExitCode::Allow.code()
        );
    }

    let mut script_args = Vec::new();
    if preflight {
        script_args.push("--preflight".to_string());
    }
    script_args.push(config.state_dir.display().to_string());
    let script_output = run_macos_vm_script(
        &script_path,
        &script_args,
        &[],
        Duration::from_secs(20 * 60),
    );
    let exit_code = script_output
        .exit_code
        .unwrap_or_else(|| ExitCode::InternalError.code());
    let mutation = execute && exit_code == ExitCode::Allow.code();
    let status = if preflight { "preflight" } else { "execute" };
    format!(
        "whoathere vm reprovision\nrelease_target={}\nstate_dir={}\nmutation={mutation}\npreflight_requested={preflight}\nexecute_requested={execute}\nstatus={status}\nadmin_required_for_execute={}\nreprovision_command={}\n{}\nexit_code={exit_code}",
        RELEASE_TARGET,
        config.state_dir.display(),
        true,
        reprovision_command,
        script_output.render_text()
    )
}

fn render_vm_validate_npm_uv(
    state_dir: Option<&str>,
    helper_path: Option<&str>,
    execute: bool,
) -> String {
    let config = macos_vm_config(state_dir, None, None);
    let script_path = match resolve_helper_script_path(
        helper_path,
        "validate-npm-uv-detonation.sh",
        "npm_uv_validation_script_not_found",
    ) {
        Ok(path) => path,
        Err(reason_code) => {
            return format!(
                "whoathere vm validate-npm-uv\nrelease_target={}\nstate_dir={}\nmutation=false\nexecute_requested={execute}\nstatus=error\nreason_code={reason_code}\nexit_code={}",
                RELEASE_TARGET,
                config.state_dir.display(),
                ExitCode::Misuse.code()
            );
        }
    };
    let validation_command = format!(
        "{} vm validate-npm-uv --state-dir {} --helper {} --execute",
        std::env::current_exe()
            .ok()
            .map(|path| shell_quote(&path.display().to_string()))
            .unwrap_or_else(|| "whoathere".to_string()),
        shell_quote(&config.state_dir.display().to_string()),
        shell_quote(
            &configured_macos_vm_helper_path(helper_path)
                .map(|path| path.display().to_string())
                .unwrap_or_else(|| "missing".to_string())
        )
    );
    if !execute {
        return format!(
            "whoathere vm validate-npm-uv\nrelease_target={}\nstate_dir={}\nmutation=false\nexecute_requested=false\nstatus=dry_run\nscript_path={}\nvalidation_command={}\nexplanation=run with --execute after guest provisioning proves Node/npm and uv\nexit_code={}",
            RELEASE_TARGET,
            config.state_dir.display(),
            redacted_scalar(&script_path.display().to_string()),
            validation_command,
            ExitCode::Allow.code()
        );
    }

    let whoathere_bin = std::env::current_exe()
        .ok()
        .map(|path| path.display().to_string())
        .unwrap_or_else(|| "whoathere".to_string());
    let helper = configured_macos_vm_helper_path(helper_path)
        .map(|path| path.display().to_string())
        .unwrap_or_default();
    let extra_env = vec![
        (
            "WHOATHERE_VM_STATE_DIR",
            config.state_dir.display().to_string(),
        ),
        ("WHOATHERE_MACOS_VM_HELPER", helper),
        ("WHOATHERE_BIN", whoathere_bin),
    ];
    let script_output =
        run_macos_vm_script(&script_path, &[], &extra_env, Duration::from_secs(30 * 60));
    let exit_code = script_output
        .exit_code
        .unwrap_or_else(|| ExitCode::InternalError.code());
    let mutation = exit_code == ExitCode::Allow.code();
    format!(
        "whoathere vm validate-npm-uv\nrelease_target={}\nstate_dir={}\nmutation={mutation}\nexecute_requested=true\nstatus=execute\nvalidation_command={}\n{}\nexit_code={exit_code}",
        RELEASE_TARGET,
        config.state_dir.display(),
        validation_command,
        script_output.render_text()
    )
}

fn render_vm_action(
    action: VmAction,
    state_dir: Option<&str>,
    helper_path: Option<&str>,
    execute: bool,
) -> String {
    let action_name = match action {
        VmAction::Start => "start",
        VmAction::Suspend => "suspend",
        VmAction::Reset => "reset",
        VmAction::Prune => "prune",
        VmAction::Health => "health",
        VmAction::UpgradeLocalManifest => "upgrade-local-manifest",
    };
    let config = macos_vm_config(state_dir, None, None);
    if matches!(action, VmAction::Health) {
        let helper = run_macos_vm_helper(
            helper_path,
            action_name,
            &[
                "--state-dir".to_string(),
                config.state_dir.display().to_string(),
                "--json".to_string(),
            ],
        );
        let exit_code = helper.exit_code.unwrap_or_else(|| ExitCode::Misuse.code());
        return format!(
            "whoathere vm {action_name}\nrelease_target={}\nstate_dir={}\nmutation=false\nready=false\n{}\nexit_code={exit_code}",
            RELEASE_TARGET,
            config.state_dir.display(),
            helper.render_text()
        );
    }
    if execute {
        let helper = run_macos_vm_helper(
            helper_path,
            action_name,
            &[
                "--state-dir".to_string(),
                config.state_dir.display().to_string(),
                "--execute".to_string(),
                "--json".to_string(),
            ],
        );
        let exit_code = helper.exit_code.unwrap_or_else(|| ExitCode::Misuse.code());
        let mutation = exit_code == ExitCode::Allow.code();
        return format!(
            "whoathere vm {action_name}\nrelease_target={}\nstate_dir={}\nmutation_requested=true\nmutation={mutation}\nready=false\n{}\nexit_code={exit_code}",
            RELEASE_TARGET,
            config.state_dir.display(),
            helper.render_text()
        );
    }
    format!(
        "whoathere vm {action_name}\nrelease_target={}\nstate_dir={}\nmutation={}\nstatus=dry_run\nexit_code={}\nready=false\nreason_code=execute_required_for_mutation\nexplanation=rerun with --execute and a configured macOS VM helper to perform lifecycle mutation",
        RELEASE_TARGET,
        config.state_dir.display(),
        execute,
        ExitCode::Allow.code()
    )
}

