#[derive(Debug, Clone, PartialEq, Eq)]
struct MacosVmScriptOutput {
    script_path: String,
    available: bool,
    exit_code: Option<i32>,
    stdout: String,
    stderr: String,
    stdout_truncated: bool,
    stderr_truncated: bool,
    reason_codes: Vec<String>,
}

impl MacosVmScriptOutput {
    fn render_text(&self) -> String {
        format!(
            "script_path={}\nscript_available={}\nscript_exit_code={}\nscript_reason_codes={:?}\nscript_stdout_truncated={}\nscript_stderr_truncated={}\nscript_stdout={}\nscript_stderr={}",
            redacted_scalar(&self.script_path),
            self.available,
            self.exit_code
                .map(|code| code.to_string())
                .unwrap_or_else(|| "none".to_string()),
            self.reason_codes,
            self.stdout_truncated,
            self.stderr_truncated,
            single_line(&redacted_helper_stream(&self.stdout)),
            single_line(&redacted_helper_stream(&self.stderr))
        )
    }
}

fn run_macos_vm_script(
    script_path: &Path,
    script_args: &[String],
    extra_env: &[(&str, String)],
    timeout: Duration,
) -> MacosVmScriptOutput {
    let mut command = ProcessCommand::new(script_path);
    command
        .args(script_args)
        .env_clear()
        .env(
            "PATH",
            "/usr/bin:/bin:/usr/sbin:/sbin:/opt/homebrew/bin:/usr/local/bin",
        )
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for env_name in ["HOME", "SUDO_USER", "TMPDIR", "USER", "LOGNAME"] {
        if let Ok(value) = std::env::var(env_name) {
            command.env(env_name, value);
        }
    }
    if let Some(python_runtime_dir) = detect_python_runtime_dir_for_reprovision() {
        command.env("WHOATHERE_PYTHON_RUNTIME_DIR", python_runtime_dir);
    }
    if let Some(python_wheel_dir) = detect_python_wheel_dir_for_reprovision() {
        command.env("WHOATHERE_PYTHON_WHEEL_DIR", python_wheel_dir);
    }
    if let Some(wheel_package_file) = detect_wheel_package_file_for_reprovision() {
        command.env("WHOATHERE_WHEEL_PACKAGE_FILE", wheel_package_file);
    }
    if let Some(node_runtime_dir) = detect_node_runtime_dir_for_reprovision() {
        command.env("WHOATHERE_NODE_RUNTIME_DIR", node_runtime_dir);
    }
    if let Some(uv_binary) = detect_uv_binary_for_reprovision() {
        command.env("WHOATHERE_UV_BINARY", uv_binary);
    }
    for (name, value) in extra_env {
        command.env(name, value);
    }

    match command.spawn() {
        Ok(mut child) => {
            let stdout_reader = spawn_limited_reader(child.stdout.take());
            let stderr_reader = spawn_limited_reader(child.stderr.take());
            let deadline = Instant::now() + timeout;
            let mut timed_out = false;
            let status = loop {
                match child.try_wait() {
                    Ok(Some(status)) => break Some(status),
                    Ok(None) if Instant::now() >= deadline => {
                        timed_out = true;
                        let _ = child.kill();
                        break child.wait().ok();
                    }
                    Ok(None) => sleep(Duration::from_millis(25)),
                    Err(_) => break None,
                }
            };
            let (stdout, stdout_truncated) = join_limited_reader(stdout_reader);
            let (stderr, stderr_truncated) = join_limited_reader(stderr_reader);
            let mut reason_codes = Vec::new();
            if timed_out {
                reason_codes.push("macos_vm_script_timeout".to_string());
            } else if !status.map(|status| status.success()).unwrap_or(false) {
                reason_codes.push("macos_vm_script_failed".to_string());
            }
            if stdout_truncated {
                reason_codes.push("macos_vm_script_stdout_truncated".to_string());
            }
            if stderr_truncated {
                reason_codes.push("macos_vm_script_stderr_truncated".to_string());
            }
            MacosVmScriptOutput {
                script_path: script_path.display().to_string(),
                available: true,
                exit_code: status
                    .and_then(|status| status.code())
                    .or(Some(ExitCode::InternalError.code())),
                stdout,
                stderr,
                stdout_truncated,
                stderr_truncated,
                reason_codes,
            }
        }
        Err(error) => MacosVmScriptOutput {
            script_path: script_path.display().to_string(),
            available: true,
            exit_code: Some(ExitCode::InternalError.code()),
            stdout: String::new(),
            stderr: error.to_string(),
            stdout_truncated: false,
            stderr_truncated: false,
            reason_codes: vec!["macos_vm_script_spawn_failed".to_string()],
        },
    }
}

