const MACOS_LOCAL_RELEASE_READINESS_SCHEMA_VERSION: &str =
    "whoathere.macos_local_release_readiness.v1";

#[derive(Debug, Clone, PartialEq, Eq)]
struct MacosLocalReleaseReadiness {
    schema_version: &'static str,
    release_ready: bool,
    release_stage: &'static str,
    scanner_release_blocking: bool,
    scanner_release_scope: &'static str,
    package_acquisition_policy: &'static str,
    implemented_workflows: Vec<String>,
    fail_closed_workflows: Vec<String>,
    manual_review_classes: Vec<String>,
    blocking_reason_codes: Vec<String>,
    next_actions: Vec<String>,
}

struct MacosLocalReleaseEvidence<'a> {
    provisioning: &'a MacosVmGuestProvisioningSummary,
    release_validation: &'a MacosVmReleaseValidationSummary,
    sync_validation: &'a MacosVmSyncValidationSummary,
    release_notarization: &'a MacosVmReleaseNotarizationSummary,
    expected_provisioning_digest: Option<&'a str>,
}

fn macos_local_release_readiness(
    status: &whoathere_macos_vm::MacosVmStatus,
    evidence: MacosLocalReleaseEvidence<'_>,
    helper: &MacosVmHelperOutput,
    _scanner_available_count: usize,
    _scanner_required_count: usize,
) -> MacosLocalReleaseReadiness {
    let mut blocking_reason_codes = vm_lifecycle_reason_codes(status, helper);
    blocking_reason_codes.extend(evidence.provisioning.reason_codes());
    blocking_reason_codes.extend(helper.reason_codes.iter().cloned());

    if !helper.available {
        blocking_reason_codes.push("macos_vm_helper_unavailable".to_string());
    }
    if helper.available && helper.exit_code != Some(0) {
        blocking_reason_codes.push("macos_vm_helper_status_not_clean".to_string());
    }
    let scanner_release_blocking = false;
    if scanner_release_blocking {
        blocking_reason_codes.push("release_required_scanners_missing".to_string());
    }

    if !evidence
        .release_validation
        .npm_verified(evidence.expected_provisioning_digest)
    {
        blocking_reason_codes.push("release_npm_vm_detonation_not_verified".to_string());
    }
    if !evidence
        .release_validation
        .uv_verified(evidence.expected_provisioning_digest)
    {
        blocking_reason_codes.push("release_uv_vm_detonation_not_verified".to_string());
    }
    if !evidence
        .sync_validation
        .verified(evidence.expected_provisioning_digest)
    {
        blocking_reason_codes.push("release_sync_back_validation_not_verified".to_string());
        blocking_reason_codes.extend(
            evidence
                .sync_validation
                .reason_codes(evidence.expected_provisioning_digest),
        );
    }
    if !evidence.release_notarization.verified() {
        blocking_reason_codes.push("release_signature_notarization_not_complete".to_string());
    }
    blocking_reason_codes.sort();
    blocking_reason_codes.dedup();
    let mut next_actions = Vec::new();
    if blocking_reason_codes
        .iter()
        .any(|reason| reason.starts_with("macos_vm_guest"))
    {
        next_actions.push(
            "reprovision the stopped VM with explicit Node/npm and uv tool sources until receipt and health prove toolchains"
                .to_string(),
        );
    }
    if blocking_reason_codes.iter().any(|reason| {
        reason == "release_npm_vm_detonation_not_verified"
            || reason == "release_uv_vm_detonation_not_verified"
    }) {
        next_actions.push(
            "run live npm and uv VM detonation validation, then suspend the VM after validation"
                .to_string(),
        );
    }
    if blocking_reason_codes
        .iter()
        .any(|reason| reason == "release_sync_back_validation_not_verified")
    {
        next_actions.push(
            "run a supported clean VM detonation with --sync-back to produce a current sync-validation receipt"
                .to_string(),
        );
    }
    if blocking_reason_codes
        .iter()
        .any(|reason| reason == "release_signature_notarization_not_complete")
    {
        next_actions.push(
            "complete Developer ID signing and Apple notarization for the preview artifact"
                .to_string(),
        );
    }
    if blocking_reason_codes.is_empty() {
        next_actions.push(
            "release candidate is ready for clean-host Apple Silicon install smoke testing"
                .to_string(),
        );
    }
    next_actions.push("run whoathere vm red-team-gate on every release candidate".to_string());

    MacosLocalReleaseReadiness {
        schema_version: MACOS_LOCAL_RELEASE_READINESS_SCHEMA_VERSION,
        release_ready: blocking_reason_codes.is_empty(),
        release_stage: if blocking_reason_codes.is_empty() {
            "release_candidate"
        } else {
            "pre_release_checkpoint"
        },
        scanner_release_blocking,
        scanner_release_scope: "advisory_for_local_beta_required_before_public_package_auto_sync",
        package_acquisition_policy: "local_only_no_public_resolver",
        implemented_workflows: string_vec(&[
            "pip.local_project.install",
            "pip.local_requirements.local_only",
            "npm.local_project.no_external_dependency_plan",
            "uv.pip_install.local_project_plan",
            "package_acquisition.local_only_no_public_resolver",
            "host.sync_back.local_beta_allowlist",
            "vm.fixture_detonation",
            "vm.release_plan.admission_model",
            "package_risk.local_memory",
            "package_risk.last_known_good",
            "package_risk.cooldown_and_diff_gates",
            "package_risk.local_artifact_review_optional",
        ]),
        fail_closed_workflows: string_vec(&[
            "npm.install.project.live_until_guest_toolchain_proven",
            "npm.ci.project.live_until_guest_toolchain_proven",
            "npm.public_dependency_resolution",
            "npm.exec_or_npx",
            "uv.sync.deferred_until_lock_policy",
            "uv.pip_install.live_until_guest_toolchain_proven",
            "pip.public_index_resolution",
            "host.sync_back.unsupported_or_unverified_outputs",
        ]),
        manual_review_classes: string_vec(&[
            "native_extensions",
            "binary_wheels",
            "direct_urls",
            "vcs_dependencies",
            "editable_installs",
            "unsupported_unknown_artifacts",
        ]),
        blocking_reason_codes,
        next_actions,
    }
}

fn string_vec(values: &[&str]) -> Vec<String> {
    values.iter().map(|value| (*value).to_string()).collect()
}

fn render_doctor(json: bool, state_dir: Option<&str>, helper_path: Option<&str>) -> String {
    let backend = UnsupportedBackend;
    let plan = backend.plan(ExecutionMode::Protected);
    let config = macos_vm_config(state_dir, None, None);
    let default_manifest_path = default_macos_vm_manifest_path(&config);
    let provisioning_path = default_macos_vm_guest_provisioning_path(&config);
    let shutdown_path = default_macos_vm_runtime_shutdown_path(&config);
    let release_validation_path = default_macos_vm_release_validation_path(&config);
    let sync_validation_path = default_macos_vm_sync_validation_path(&config);
    let release_notarization_path = default_macos_vm_release_notarization_path(&config);
    let (manifest, manifest_load_reason, effective_manifest_path) =
        load_macos_vm_manifest(None, &default_manifest_path);
    let provisioning = load_macos_vm_guest_provisioning(&provisioning_path, helper_path);
    let shutdown = load_macos_vm_runtime_shutdown(&shutdown_path);
    let provisioning_digest = file_sha256_digest(&provisioning_path);
    let release_validation =
        load_macos_vm_release_validation(&release_validation_path, &config.state_dir);
    let sync_validation = load_macos_vm_sync_validation(&sync_validation_path, &config.state_dir)
        .with_runtime_artifacts(helper_path);
    let release_notarization =
        load_macos_vm_release_notarization(&release_notarization_path, &config.state_dir)
            .with_runtime_artifacts(helper_path);
    let status = status_from_config(&config, HostPlatform::current(), manifest.as_ref());
    let helper = run_macos_vm_helper(
        helper_path,
        "status",
        &[
            "--state-dir".to_string(),
            config.state_dir.display().to_string(),
            "--json".to_string(),
        ],
    );
    let effective_vm_reason_codes = effective_vm_reason_codes(&status, &helper);
    let vm_lifecycle_reason_codes = vm_lifecycle_reason_codes(&status, &helper);
    let scanner_inventory = scanner_inventory();
    let scanner_available = scanner_inventory
        .iter()
        .filter(|item| item.spec.role == ScannerExecutionRole::Core && item.available)
        .count();
    let scanner_required = scanner_inventory
        .iter()
        .filter(|item| item.spec.role == ScannerExecutionRole::Core)
        .count();
    let scanner_bootstrap = scanner_bootstrap_receipt_readiness(&scanner_inventory);
    let scanner_public_package_auto_trust_ready = scanner_bootstrap.public_auto_trust_ready;
    let package_memory_ready = package_risk_memory_ready(&config.state_dir);
    let package_risk_gate_ready = true;
    let package_reputation_support = "local_metadata_only";
    let readiness = macos_local_release_readiness(
        &status,
        MacosLocalReleaseEvidence {
            provisioning: &provisioning,
            release_validation: &release_validation,
            sync_validation: &sync_validation,
            release_notarization: &release_notarization,
            expected_provisioning_digest: provisioning_digest.as_deref(),
        },
        &helper,
        scanner_available,
        scanner_required,
    );
    let guest_reprovision_command = guest_reprovision_command(
        helper.configured_path.as_deref(),
        &config.state_dir,
        &provisioning,
    );
    let guest_reprovision_operator_action =
        guest_reprovision_operator_action(&provisioning, guest_reprovision_command.as_deref());
    if json {
        let scanner_json = scanner_inventory
            .iter()
            .map(|item| {
                format!(
                    "{{\"name\": {}, \"available\": {}, \"role\": {}, \"required_for_auto_sync\": {}, \"path\": {}, \"version\": {}, \"evidence_role\": {}}}",
                    json_string(item.spec.name),
                    item.available,
                    json_string(item.spec.role.as_str()),
                    item.spec.role == ScannerExecutionRole::Core,
                    item.display_path
                        .as_deref()
                        .map(json_string)
                        .unwrap_or_else(|| "null".to_string()),
                    item.version
                        .as_deref()
                        .map(json_string)
                        .unwrap_or_else(|| "null".to_string()),
                    json_string(item.spec.evidence_role)
                )
            })
            .collect::<Vec<_>>()
            .join(", ");
        return format!(
            "{{\n  \"command\": \"whoathere doctor\",\n  \"status\": \"ok\",\n  \"release_target\": {},\n  \"release_claim\": {},\n  \"sandbox_label\": {},\n  \"high_risk_allowed\": {},\n  \"state_dir\": {},\n  \"vm_manifest_path\": {},\n  \"vm_manifest_load_reason\": {},\n  \"guest_provisioning\": {},\n  \"runtime_shutdown\": {},\n  \"release_validation\": {},\n  \"sync_validation\": {},\n  \"release_notarization\": {},\n  \"guest_reprovision_required\": {},\n  \"guest_reprovision_admin_required\": {},\n  \"guest_reprovision_operator_action\": {},\n  \"guest_reprovision_command\": {},\n  \"release_readiness_schema\": {},\n  \"release_stage\": {},\n  \"release_ready\": {},\n  \"release_blocking_reason_codes\": {},\n  \"scanner_release_blocking\": {},\n  \"scanner_release_scope\": {},\n  \"scanner_bootstrap_receipt_present\": {},\n  \"scanner_bootstrap_receipt_path\": {},\n  \"scanner_bootstrap_receipt_valid\": {},\n  \"scanner_bootstrap_receipt_reason_codes\": {},\n  \"scanner_public_package_auto_trust_ready\": {},\n  \"package_memory_ready\": {},\n  \"package_memory_path\": {},\n  \"package_risk_gate_ready\": {},\n  \"package_age_gate_days\": {},\n  \"package_diff_supported\": {},\n  \"package_reputation_support\": {},\n  \"artifact_review_support\": \"optional_local_ollama_findings_only\",\n  \"artifact_review_auto_allow_authority\": false,\n  \"package_acquisition_policy\": {},\n  \"implemented_workflows\": {},\n  \"fail_closed_workflows\": {},\n  \"manual_review_classes\": {},\n  \"next_actions\": {},\n  \"vm_lifecycle_ready\": {},\n  \"vm_lifecycle_reason_codes\": {},\n  \"vm_runtime_ready\": {},\n  \"vm_ready\": {},\n  \"vm_reason_codes\": {},\n  \"helper_path\": {},\n  \"helper_available\": {},\n  \"helper_exit_code\": {},\n  \"helper_reason_codes\": {},\n  \"helper_stdout_truncated\": {},\n  \"helper_stderr_truncated\": {},\n  \"helper_stdout\": {},\n  \"helper_stderr\": {},\n  \"scanner_available_count\": {},\n  \"scanner_required_count\": {},\n  \"scanners\": [{}]\n}}",
            json_string(RELEASE_TARGET),
            json_string(RELEASE_CLAIM),
            json_string(plan.label),
            plan.high_risk_allowed,
            json_string(&config.state_dir.display().to_string()),
            json_string(&effective_manifest_path),
            manifest_load_reason
                .as_deref()
                .map(json_string)
                .unwrap_or_else(|| "null".to_string()),
            render_guest_provisioning_json(&provisioning),
            render_runtime_shutdown_json(&shutdown),
            render_release_validation_json(&release_validation, provisioning_digest.as_deref()),
            render_sync_validation_json(&sync_validation, provisioning_digest.as_deref()),
            render_release_notarization_json(&release_notarization),
            guest_reprovision_required(&provisioning),
            guest_reprovision_admin_required(&provisioning),
            json_string(guest_reprovision_operator_action),
            guest_reprovision_command
                .as_deref()
                .map(json_string)
                .unwrap_or_else(|| "null".to_string()),
            json_string(readiness.schema_version),
            json_string(readiness.release_stage),
            readiness.release_ready,
            json_string_array(&readiness.blocking_reason_codes),
            readiness.scanner_release_blocking,
            json_string(readiness.scanner_release_scope),
            scanner_bootstrap.present,
            json_string(&redacted_path_string(&scanner_bootstrap_receipt_path())),
            scanner_bootstrap.valid,
            json_string_array(&scanner_bootstrap.reason_codes),
            scanner_public_package_auto_trust_ready,
            package_memory_ready,
            json_string(&redacted_package_risk_path(&package_risk_store_path(&config.state_dir))),
            package_risk_gate_ready,
            PACKAGE_RISK_COOLDOWN_DAYS,
            true,
            json_string(package_reputation_support),
            json_string(readiness.package_acquisition_policy),
            json_string_array(&readiness.implemented_workflows),
            json_string_array(&readiness.fail_closed_workflows),
            json_string_array(&readiness.manual_review_classes),
            json_string_array(&readiness.next_actions),
            vm_lifecycle_reason_codes.is_empty(),
            json_string_array(&vm_lifecycle_reason_codes),
            effective_vm_reason_codes.is_empty(),
            effective_vm_reason_codes.is_empty(),
            json_string_array(&effective_vm_reason_codes),
            helper
                .configured_path
                .as_deref()
                .map(json_string)
                .unwrap_or_else(|| "null".to_string()),
            helper.available,
            helper
                .exit_code
                .map(|code| code.to_string())
                .unwrap_or_else(|| "null".to_string()),
            json_string_array(&helper.reason_codes),
            helper.stdout_truncated,
            helper.stderr_truncated,
            json_string(&single_line(&redacted_helper_stream(&helper.stdout))),
            json_string(&single_line(&redacted_helper_stream(&helper.stderr))),
            scanner_available,
            scanner_required,
            scanner_json
        );
    }
    let scanner_lines = scanner_inventory
        .iter()
        .map(|item| {
            format!(
                "scanner_adapter={} available={} role={} required_for_auto_sync={} path={} version={} evidence_role=\"{}\"",
                item.spec.name,
                item.available,
                item.spec.role.as_str(),
                item.spec.role == ScannerExecutionRole::Core,
                item.display_path.as_deref().unwrap_or("none"),
                item.version.as_deref().unwrap_or("unknown"),
                item.spec.evidence_role
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere doctor\nstatus=ok\nrelease_target={}\nrelease_claim={}\nsandbox_label={}\nhigh_risk_allowed={}\nstate_dir={}\nvm_manifest_path={}\nvm_manifest_load_reason={}\n{}\n{}\n{}\n{}\n{}\nguest_reprovision_required={}\nguest_reprovision_admin_required={}\nguest_reprovision_operator_action={}\nguest_reprovision_command={}\nrelease_readiness_schema={}\nrelease_stage={}\nrelease_ready={}\nrelease_blocking_reason_codes={:?}\nscanner_release_blocking={}\nscanner_release_scope={}\nscanner_bootstrap_receipt_present={}\nscanner_bootstrap_receipt_path={}\nscanner_bootstrap_receipt_valid={}\nscanner_bootstrap_receipt_reason_codes={:?}\nscanner_public_package_auto_trust_ready={}\npackage_memory_ready={}\npackage_memory_path={}\npackage_risk_gate_ready={}\npackage_age_gate_days={}\npackage_diff_supported=true\npackage_reputation_support={}\nartifact_review_support=optional_local_ollama_findings_only\nartifact_review_auto_allow_authority=false\npackage_acquisition_policy={}\nimplemented_workflows={:?}\nfail_closed_workflows={:?}\nmanual_review_classes={:?}\nnext_actions={:?}\nvm_lifecycle_ready={}\nvm_lifecycle_reason_codes={:?}\nvm_runtime_ready={}\nvm_ready={}\nvm_reason_codes={:?}\n{}\nscanner_available_count={}\nscanner_required_count={}\n{}",
        RELEASE_TARGET,
        RELEASE_CLAIM,
        plan.label,
        plan.high_risk_allowed,
        config.state_dir.display(),
        effective_manifest_path,
        manifest_load_reason.unwrap_or_else(|| "none".to_string()),
        provisioning.render_text(),
        render_runtime_shutdown_text(&shutdown),
        render_release_validation_text(&release_validation, provisioning_digest.as_deref()),
        render_sync_validation_text(&sync_validation, provisioning_digest.as_deref()),
        render_release_notarization_text(&release_notarization),
        guest_reprovision_required(&provisioning),
        guest_reprovision_admin_required(&provisioning),
        guest_reprovision_operator_action,
        guest_reprovision_command
            .as_deref()
            .unwrap_or("none"),
        readiness.schema_version,
        readiness.release_stage,
        readiness.release_ready,
        readiness.blocking_reason_codes,
        readiness.scanner_release_blocking,
        readiness.scanner_release_scope,
        scanner_bootstrap.present,
        redacted_path_string(&scanner_bootstrap_receipt_path()),
        scanner_bootstrap.valid,
        scanner_bootstrap.reason_codes,
        scanner_public_package_auto_trust_ready,
        package_memory_ready,
        redacted_package_risk_path(&package_risk_store_path(&config.state_dir)),
        package_risk_gate_ready,
        PACKAGE_RISK_COOLDOWN_DAYS,
        package_reputation_support,
        readiness.package_acquisition_policy,
        readiness.implemented_workflows,
        readiness.fail_closed_workflows,
        readiness.manual_review_classes,
        readiness.next_actions,
        vm_lifecycle_reason_codes.is_empty(),
        vm_lifecycle_reason_codes,
        effective_vm_reason_codes.is_empty(),
        effective_vm_reason_codes.is_empty(),
        effective_vm_reason_codes,
        helper.render_summary_text(),
        scanner_available,
        scanner_required,
        scanner_lines
    )
}

fn render_vm_release_plan(args: VmReleasePlanArgs<'_>) -> String {
    let config = macos_vm_config(args.state_dir, None, None);
    let package_class = match package_class_from_release_args(&args) {
        Ok(package_class) => package_class,
        Err(reason) => {
            if args.json {
                return format!(
                    "{{\n  \"command\": \"whoathere vm release-plan\",\n  \"status\": \"error\",\n  \"reason_code\": {},\n  \"exit_code\": {}\n}}",
                    json_string(reason),
                    ExitCode::Misuse.code()
                );
            }
            return format!(
                "whoathere vm release-plan\nstatus=error\nreason_code={reason}\nexit_code={}",
                ExitCode::Misuse.code()
            );
        }
    };
    let (mut effective_evidence, mut package_risk_receipt) = apply_package_risk_receipt(
        args.evidence.clone(),
        args.package_risk_receipt,
        Some(&config.state_dir),
        args.package_risk_receipt.is_some(),
    );
    let public_package_gate_reasons = enforce_public_package_receipt_requirements(
        package_class,
        &mut effective_evidence,
        &mut package_risk_receipt,
    );
    let workspace_gate_reasons = enforce_release_plan_package_risk_workspace(
        args.workspace,
        &mut effective_evidence,
        &package_risk_receipt,
    );
    let mut decision = decide_local_sync(package_class, &effective_evidence);
    decision
        .reason_codes
        .extend(public_package_gate_reasons.iter().cloned());
    decision
        .reason_codes
        .extend(workspace_gate_reasons.iter().cloned());
    decision.reason_codes.sort();
    decision.reason_codes.dedup();
    let exit_code = local_admission_exit_code(decision.verdict);
    if args.json {
        return format!(
            "{{\n  \"command\": \"whoathere vm release-plan\",\n  \"release_target\": {},\n  \"release_claim\": {},\n  \"vm_boundary\": {},\n  \"network_model\": {},\n  \"sync_policy\": {},\n  \"authorization\": false,\n  \"sync_authorized\": false,\n  \"authorization_reason\": \"release_plan_is_not_runtime_verdict\",\n  \"package_class\": {},\n  \"verdict\": {},\n  \"auto_sync_eligible\": {},\n  \"sync_paths\": {},\n  \"required_evidence\": {},\n  \"reason_codes\": {},\n  \"package_risk_receipt\": {},\n  \"package_risk_receipt_applied\": {},\n  \"package_risk_reason_codes\": {},\n  \"evidence\": {{\"vm_ready\": {}, \"static_clean\": {}, \"dynamic_clean\": {}, \"egress_clean\": {}, \"no_canary_access\": {}, \"scanner_clean\": {}, \"diff_clean_or_baseline_absent\": {}, \"freshness_allowed\": {}}},\n  \"exit_code\": {exit_code}\n}}",
            json_string(RELEASE_TARGET),
            json_string(RELEASE_CLAIM),
            json_string(VM_BOUNDARY),
            json_string(NETWORK_MODEL),
            json_string(SYNC_POLICY),
            json_string(package_class.as_str()),
            json_string(decision.verdict.as_str()),
            decision.auto_sync_eligible,
            json_string_array(
                &decision
                    .sync_paths
                    .iter()
                    .map(|path| (*path).to_string())
                    .collect::<Vec<_>>()
            ),
            json_string_array(
                &decision
                    .required_evidence
                    .iter()
                    .map(|evidence| (*evidence).to_string())
                    .collect::<Vec<_>>()
            ),
            json_string_array(&decision.reason_codes),
            package_risk_receipt
                .receipt_path
                .as_deref()
                .map(json_string)
                .unwrap_or_else(|| "null".to_string()),
            package_risk_receipt.applied,
            json_string_array(&package_risk_receipt.reason_codes),
            effective_evidence.vm_ready,
            effective_evidence.static_clean,
            effective_evidence.dynamic_clean,
            effective_evidence.egress_clean,
            effective_evidence.no_canary_access,
            effective_evidence.scanner_clean,
            effective_evidence.diff_clean_or_baseline_absent,
            effective_evidence.freshness_allowed,
        );
    }
    format!(
        "whoathere vm release-plan\nrelease_target={}\nrelease_claim={}\nvm_boundary={}\nnetwork_model={}\nsync_policy={}\nauthorization=false\nsync_authorized=false\nauthorization_reason=release_plan_is_not_runtime_verdict\npackage_class={}\nverdict={}\nauto_sync_eligible={}\nsync_paths={:?}\nrequired_evidence={:?}\nreason_codes={:?}\npackage_risk_receipt={}\npackage_risk_receipt_applied={}\npackage_risk_reason_codes={:?}\nevidence_vm_ready={}\nevidence_static_clean={}\nevidence_dynamic_clean={}\nevidence_egress_clean={}\nevidence_no_canary_access={}\nevidence_scanner_clean={}\nevidence_diff_clean_or_baseline_absent={}\nevidence_freshness_allowed={}\nexit_code={exit_code}",
        RELEASE_TARGET,
        RELEASE_CLAIM,
        VM_BOUNDARY,
        NETWORK_MODEL,
        SYNC_POLICY,
        package_class.as_str(),
        decision.verdict.as_str(),
        decision.auto_sync_eligible,
        decision.sync_paths,
        decision.required_evidence,
        decision.reason_codes,
        package_risk_receipt.receipt_path.as_deref().unwrap_or("none"),
        package_risk_receipt.applied,
        package_risk_receipt.reason_codes,
        effective_evidence.vm_ready,
        effective_evidence.static_clean,
        effective_evidence.dynamic_clean,
        effective_evidence.egress_clean,
        effective_evidence.no_canary_access,
        effective_evidence.scanner_clean,
        effective_evidence.diff_clean_or_baseline_absent,
        effective_evidence.freshness_allowed,
    )
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PackageRiskReceiptApplication {
    receipt_path: Option<String>,
    applied: bool,
    authenticated: bool,
    receipt_id: Option<String>,
    workspace_sha256: Option<String>,
    created_at_unix_seconds: Option<u64>,
    overall_verdict: Option<String>,
    scanner_clean: Option<bool>,
    scanner_evidence_applied: Option<bool>,
    scanner_evidence_status: Option<String>,
    artifact_review_status: Option<String>,
    package_classes: Vec<String>,
    package_verdicts: Vec<String>,
    artifact_review_statuses: Vec<String>,
    reason_codes: Vec<String>,
}

fn apply_package_risk_receipt(
    mut evidence: LocalEvidenceFlags,
    receipt_path: Option<&str>,
    state_dir: Option<&Path>,
    require_auth: bool,
) -> (LocalEvidenceFlags, PackageRiskReceiptApplication) {
    let Some(receipt_path) = receipt_path else {
        return (
            evidence,
            PackageRiskReceiptApplication {
                receipt_path: None,
                applied: false,
                authenticated: false,
                receipt_id: None,
                workspace_sha256: None,
                created_at_unix_seconds: None,
                overall_verdict: None,
                scanner_clean: None,
                scanner_evidence_applied: None,
                scanner_evidence_status: None,
                artifact_review_status: None,
                package_classes: Vec::new(),
                package_verdicts: Vec::new(),
                artifact_review_statuses: Vec::new(),
                reason_codes: vec!["package_risk_receipt_not_provided".to_string()],
            },
        );
    };
    let redacted_path = redacted_package_risk_path(Path::new(receipt_path));
    let contents = match std::fs::read_to_string(receipt_path) {
        Ok(contents) => contents,
        Err(_) => {
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
            evidence.scanner_clean = false;
            return (
                evidence,
                PackageRiskReceiptApplication {
                    receipt_path: Some(redacted_path),
                    applied: false,
                    authenticated: false,
                    receipt_id: None,
                    workspace_sha256: None,
                    created_at_unix_seconds: None,
                    overall_verdict: None,
                    scanner_clean: None,
                    scanner_evidence_applied: None,
                    scanner_evidence_status: None,
                    artifact_review_status: None,
                    package_classes: Vec::new(),
                    package_verdicts: Vec::new(),
                    artifact_review_statuses: Vec::new(),
                    reason_codes: vec!["package_risk_receipt_unreadable".to_string()],
                },
            );
        }
    };
    if json_extract_string_field(&contents, "schema_version").as_deref()
        != Some(PACKAGE_RISK_ASSESSMENT_SCHEMA)
    {
        evidence.diff_clean_or_baseline_absent = false;
        evidence.freshness_allowed = false;
        evidence.scanner_clean = false;
        return (
            evidence,
            PackageRiskReceiptApplication {
                receipt_path: Some(redacted_path),
                applied: false,
                authenticated: false,
                receipt_id: None,
                workspace_sha256: None,
                created_at_unix_seconds: None,
                overall_verdict: None,
                scanner_clean: None,
                scanner_evidence_applied: None,
                scanner_evidence_status: None,
                artifact_review_status: None,
                package_classes: Vec::new(),
                package_verdicts: Vec::new(),
                artifact_review_statuses: Vec::new(),
                reason_codes: vec!["package_risk_receipt_schema_invalid".to_string()],
            },
        );
    }
    let receipt_id = json_extract_string_field(&contents, "receipt_id");
    let workspace_sha256 = json_extract_string_field(&contents, "workspace_sha256");
    let created_at_unix_seconds = json_extract_u64_field(&contents, "created_at_unix_seconds");
    let overall_verdict = json_extract_string_field(&contents, "overall_verdict");
    let diff_clean =
        json_extract_bool_field(&contents, "all_diff_clean_or_baseline_absent").unwrap_or(false);
    let freshness_allowed =
        json_extract_bool_field(&contents, "all_freshness_allowed").unwrap_or(false);
    let scanner_clean = json_extract_bool_field(&contents, "all_scanner_clean");
    let scanner_evidence = json_extract_object_field(&contents, "scanner_evidence");
    let scanner_evidence_applied = scanner_evidence
        .as_deref()
        .and_then(|object| json_extract_bool_field(object, "applied"));
    let scanner_evidence_status = scanner_evidence
        .as_deref()
        .and_then(|object| json_extract_string_field(object, "status"));
    let artifact_review = json_extract_object_field(&contents, "artifact_review");
    let artifact_review_status = artifact_review
        .as_deref()
        .and_then(|object| json_extract_string_field(object, "status"));
    let package_objects = json_extract_object_array(&contents, "packages");
    let workspace_subjects_valid = !package_objects.is_empty()
        && package_objects.iter().all(|object| {
            json_extract_string_field(object, "subject_kind").as_deref() == Some("workspace")
                && json_extract_string_field(object, "workspace_subject_fingerprint")
                    .as_deref()
                    .is_some_and(valid_sha256_digest_string)
        });
    let package_classes = package_objects
        .iter()
        .filter_map(|object| json_extract_string_field(object, "package_class"))
        .collect::<Vec<_>>();
    let package_verdicts = package_objects
        .iter()
        .filter_map(|object| json_extract_string_field(object, "verdict"))
        .collect::<Vec<_>>();
    let artifact_review_statuses = package_objects
        .iter()
        .filter_map(|object| json_extract_string_field(object, "artifact_review_status"))
        .collect::<Vec<_>>();
    evidence.diff_clean_or_baseline_absent = diff_clean;
    evidence.freshness_allowed = freshness_allowed;
    if let Some(scanner_clean) = scanner_clean {
        evidence.scanner_clean = scanner_clean;
    }
    let mut reason_codes = json_extract_string_array_field(&contents, "reason_codes");
    if workspace_subjects_valid {
        reason_codes.push("package_risk_workspace_subjects_bound".to_string());
    } else {
        reason_codes.push("package_risk_workspace_subject_binding_invalid".to_string());
        evidence.diff_clean_or_baseline_absent = false;
        evidence.freshness_allowed = false;
        evidence.scanner_clean = false;
    }
    if diff_clean {
        reason_codes.push("package_risk_diff_receipt_clean".to_string());
    } else {
        reason_codes.push("package_risk_diff_receipt_not_clean".to_string());
    }
    if freshness_allowed {
        reason_codes.push("package_risk_freshness_receipt_allowed".to_string());
    } else {
        reason_codes.push("package_risk_freshness_receipt_not_allowed".to_string());
    }
    if let Some(scanner_clean) = scanner_clean {
        if scanner_clean {
            reason_codes.push("package_risk_scanner_receipt_clean".to_string());
        } else {
            reason_codes.push("package_risk_scanner_receipt_not_clean".to_string());
        }
    }
    let mut authenticated = !require_auth;
    if require_auth {
        let auth_reasons =
            verify_package_risk_receipt_auth(state_dir, Path::new(receipt_path), &contents);
        authenticated = auth_reasons.is_empty();
        reason_codes.extend(auth_reasons);
        if !authenticated {
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
            evidence.scanner_clean = false;
        }
    }
    reason_codes.sort();
    reason_codes.dedup();
    (
        evidence,
        PackageRiskReceiptApplication {
            receipt_path: Some(redacted_path),
            applied: true,
            authenticated,
            receipt_id,
            workspace_sha256,
            created_at_unix_seconds,
            overall_verdict,
            scanner_clean,
            scanner_evidence_applied,
            scanner_evidence_status,
            artifact_review_status,
            package_classes,
            package_verdicts,
            artifact_review_statuses,
            reason_codes,
        },
    )
}

fn enforce_public_package_receipt_requirements(
    package_class: PackageClass,
    evidence: &mut LocalEvidenceFlags,
    receipt: &mut PackageRiskReceiptApplication,
) -> Vec<String> {
    if !package_class.auto_sync_eligible() {
        return Vec::new();
    }

    let mut reasons = Vec::new();
    if !receipt.applied {
        reasons.push("package_risk_receipt_required_for_public_package_auto_sync".to_string());
        if evidence.scanner_clean
            || evidence.diff_clean_or_baseline_absent
            || evidence.freshness_allowed
        {
            reasons.push(
                "operator_package_risk_flags_ignored_for_public_package_auto_sync".to_string(),
            );
        }
        evidence.scanner_clean = false;
        evidence.diff_clean_or_baseline_absent = false;
        evidence.freshness_allowed = false;
    } else {
        if !receipt.authenticated {
            reasons.push("package_risk_receipt_auth_invalid".to_string());
            evidence.scanner_clean = false;
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
        }
        if receipt
            .receipt_id
            .as_deref()
            .is_none_or(|receipt_id| receipt_id.trim().is_empty())
        {
            reasons.push("package_risk_receipt_id_missing".to_string());
            evidence.scanner_clean = false;
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
        }
        if receipt.overall_verdict.as_deref() != Some("auto_sync_candidate") {
            reasons.push("package_risk_receipt_verdict_not_auto_sync_candidate".to_string());
            evidence.scanner_clean = false;
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
        }
        if receipt.package_verdicts.is_empty()
            || receipt
                .package_verdicts
                .iter()
                .any(|verdict| verdict != "auto_sync_candidate")
        {
            reasons
                .push("package_risk_receipt_package_verdict_not_auto_sync_candidate".to_string());
            evidence.scanner_clean = false;
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
        }
        if receipt
            .artifact_review_statuses
            .iter()
            .any(|status| !artifact_review_status_allows_auto_sync(status))
        {
            reasons.push("package_risk_receipt_artifact_review_blocking".to_string());
            evidence.scanner_clean = false;
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
        }
        if receipt.scanner_clean != Some(true) {
            reasons.push(
                "package_risk_scanner_receipt_required_for_public_package_auto_sync".to_string(),
            );
            if evidence.scanner_clean {
                reasons
                    .push("operator_scanner_flag_ignored_for_public_package_auto_sync".to_string());
            }
            evidence.scanner_clean = false;
        }
        if receipt.scanner_evidence_applied != Some(true) {
            reasons.push("package_risk_receipt_scanner_evidence_not_applied".to_string());
            evidence.scanner_clean = false;
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
        }
        if receipt.scanner_evidence_status.as_deref() != Some("clean") {
            reasons.push("package_risk_receipt_scanner_evidence_not_clean".to_string());
            evidence.scanner_clean = false;
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
        }
        match receipt.artifact_review_status.as_deref() {
            Some(status) if artifact_review_status_allows_auto_sync(status) => {}
            Some(_) => {
                reasons.push("package_risk_receipt_artifact_review_blocking".to_string());
                evidence.scanner_clean = false;
                evidence.diff_clean_or_baseline_absent = false;
                evidence.freshness_allowed = false;
            }
            None => {
                reasons.push("package_risk_receipt_artifact_review_missing".to_string());
                evidence.scanner_clean = false;
                evidence.diff_clean_or_baseline_absent = false;
                evidence.freshness_allowed = false;
            }
        }
        if !receipt
            .package_classes
            .iter()
            .any(|receipt_class| receipt_class == package_class.as_str())
        {
            reasons.push(
                "package_risk_receipt_package_class_unbound_for_public_package_auto_sync"
                    .to_string(),
            );
            evidence.scanner_clean = false;
            evidence.diff_clean_or_baseline_absent = false;
            evidence.freshness_allowed = false;
        }
    }

    reasons.sort();
    reasons.dedup();
    receipt.reason_codes.extend(reasons.iter().cloned());
    receipt.reason_codes.sort();
    receipt.reason_codes.dedup();
    reasons
}

fn render_vm_canaries(json: bool) -> String {
    let canaries = default_canaries();
    if json {
        let canary_json = canaries
            .iter()
            .map(|canary| {
                format!(
                    "{{\"category\": {}, \"env_name\": {}, \"path_hint\": {}}}",
                    json_string(canary.category),
                    json_string(canary.env_name),
                    json_string(canary.path_hint)
                )
            })
            .collect::<Vec<_>>()
            .join(", ");
        return format!(
            "{{\n  \"command\": \"whoathere vm canaries\",\n  \"release_target\": {},\n  \"canaries\": [{}]\n}}",
            json_string(RELEASE_TARGET),
            canary_json
        );
    }
    let rows = canaries
        .iter()
        .map(|canary| {
            format!(
                "canary category={} env_name={} path_hint={}",
                canary.category,
                canary.env_name,
                redacted_scalar(canary.path_hint)
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere vm canaries\nrelease_target={}\nhost_secret_mounting=false\n{}",
        RELEASE_TARGET, rows
    )
}

fn render_vm_sync_policy(json: bool) -> String {
    let rules = default_sync_allowlist();
    let evidence = required_local_evidence();
    let scanners = scanner_adapters();
    if json {
        let rule_json = rules
            .iter()
            .map(|rule| {
                format!(
                    "{{\"path_pattern\": {}, \"reason\": {}}}",
                    json_string(rule.path_pattern),
                    json_string(rule.reason)
                )
            })
            .collect::<Vec<_>>()
            .join(", ");
        let scanner_json = scanners
            .iter()
            .map(|adapter| {
                format!(
                    "{{\"name\": {}, \"required_for_auto_sync\": {}, \"evidence_role\": {}}}",
                    json_string(adapter.name),
                    adapter.required_for_auto_sync,
                    json_string(adapter.evidence_role)
                )
            })
            .collect::<Vec<_>>()
            .join(", ");
        return format!(
            "{{\n  \"command\": \"whoathere vm sync-policy\",\n  \"release_target\": {},\n  \"sync_policy\": {},\n  \"sync_back_enabled\": true,\n  \"policy_scope\": \"local_beta_allowlist_requires_clean_vm_evidence_and_current_sync_receipt\",\n  \"auto_sync_classes\": [\"npm.local_project.no_external_dependency\", \"pypi.local_project.pure_python\", \"uv.local_project.pure_python\"],\n  \"deny_default_classes\": [\"direct_vcs_editable.v1\", \"unsupported_unknown.v1\"],\n  \"manual_review_classes\": [\"pypi.sdist_pep517.v1\", \"pypi.binary_wheel.v1\", \"native_extension.v1\"],\n  \"package_risk_required_for_public_auto_sync\": true,\n  \"package_age_gate_days\": {},\n  \"package_risk_receipt_max_age_seconds\": {},\n  \"artifact_review_policy\": \"optional_local_model_findings_block_auto_sync_no_allow_authority\",\n  \"artifact_review_auto_allow_authority\": false,\n  \"package_risk_receipt_fields\": [\"receipt_id\", \"workspace_sha256\", \"created_at_unix_seconds\", \"overall_verdict\", \"all_freshness_allowed\", \"all_diff_clean_or_baseline_absent\", \"all_scanner_clean\", \"scanner_evidence.applied\", \"scanner_evidence.status\", \"artifact_review.status\", \"packages[].package_class\", \"packages[].verdict\", \"packages[].artifact_review_status\", \"receipt_auth.schema_version\", \"receipt_auth.payload_sha256\", \"receipt_auth.mac_sha256\"],\n  \"sync_allowlist\": [{}],\n  \"required_evidence\": {},\n  \"scanner_adapters\": [{}]\n}}",
            json_string(RELEASE_TARGET),
            json_string(SYNC_POLICY),
            PACKAGE_RISK_COOLDOWN_DAYS,
            PACKAGE_RISK_RECEIPT_MAX_AGE_SECONDS,
            rule_json,
            json_string_array(&evidence.iter().map(|item| (*item).to_string()).collect::<Vec<_>>()),
            scanner_json
        );
    }
    let rule_rows = rules
        .iter()
        .map(|rule| {
            format!(
                "sync_allow path_pattern={} reason=\"{}\"",
                rule.path_pattern, rule.reason
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let scanner_rows = scanners
        .iter()
        .map(|adapter| {
            format!(
                "scanner_adapter={} required_for_auto_sync={} evidence_role=\"{}\"",
                adapter.name, adapter.required_for_auto_sync, adapter.evidence_role
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere vm sync-policy\nrelease_target={}\nsync_policy={}\nsync_back_enabled=true\npolicy_scope=local_beta_allowlist_requires_clean_vm_evidence_and_current_sync_receipt\nauto_sync_classes=[\"npm.local_project.no_external_dependency\", \"pypi.local_project.pure_python\", \"uv.local_project.pure_python\"]\nmanual_review_classes=[\"pypi.sdist_pep517.v1\", \"pypi.binary_wheel.v1\", \"native_extension.v1\"]\ndeny_default_classes=[\"direct_vcs_editable.v1\", \"unsupported_unknown.v1\"]\npackage_risk_required_for_public_auto_sync=true\npackage_age_gate_days={}\npackage_risk_receipt_max_age_seconds={}\nartifact_review_policy=optional_local_model_findings_block_auto_sync_no_allow_authority\nartifact_review_auto_allow_authority=false\npackage_risk_receipt_fields=[\"receipt_id\", \"workspace_sha256\", \"created_at_unix_seconds\", \"overall_verdict\", \"all_freshness_allowed\", \"all_diff_clean_or_baseline_absent\", \"all_scanner_clean\", \"scanner_evidence.applied\", \"scanner_evidence.status\", \"artifact_review.status\", \"packages[].package_class\", \"packages[].verdict\", \"packages[].artifact_review_status\", \"receipt_auth.schema_version\", \"receipt_auth.payload_sha256\", \"receipt_auth.mac_sha256\"]\nrequired_evidence={:?}\n{}\n{}",
        RELEASE_TARGET,
        SYNC_POLICY,
        PACKAGE_RISK_COOLDOWN_DAYS,
        PACKAGE_RISK_RECEIPT_MAX_AGE_SECONDS,
        evidence,
        rule_rows,
        scanner_rows
    )
}

#[derive(Debug, Clone)]
struct RedTeamGateCase {
    name: &'static str,
    category: &'static str,
    comparator: &'static str,
    path: &'static str,
    body: String,
    expected_status: u16,
    required_markers: Vec<&'static str>,
    forbidden_markers: Vec<&'static str>,
}

#[derive(Debug, Clone)]
struct RedTeamGateCaseResult {
    name: &'static str,
    category: &'static str,
    comparator: &'static str,
    expected_status: u16,
    actual_status: u16,
    passed: bool,
    reason_codes: Vec<String>,
}

fn render_vm_red_team_gate(json: bool) -> String {
    let cases = red_team_gate_cases();
    let results = cases.iter().map(run_red_team_gate_case).collect::<Vec<_>>();
    let passed = results.iter().all(|result| result.passed);
    let exit_code = if passed {
        ExitCode::Allow.code()
    } else {
        ExitCode::Deny.code()
    };
    let unavailable_scanners = scanner_inventory()
        .into_iter()
        .filter(|item| !item.available)
        .map(|item| item.spec.name.to_string())
        .collect::<Vec<_>>();

    if json {
        let case_json = results
            .iter()
            .map(|result| {
                format!(
                    "{{\"name\": {}, \"category\": {}, \"comparator\": {}, \"expected_status\": {}, \"actual_status\": {}, \"passed\": {}, \"reason_codes\": {}}}",
                    json_string(result.name),
                    json_string(result.category),
                    json_string(result.comparator),
                    result.expected_status,
                    result.actual_status,
                    result.passed,
                    json_string_array(&result.reason_codes)
                )
            })
            .collect::<Vec<_>>()
            .join(", ");
        return format!(
            "{{\n  \"command\": \"whoathere vm red-team-gate\",\n  \"release_target\": {},\n  \"release_claim\": {},\n  \"gate_scope\": \"fixture_safe_local_no_arbitrary_execution\",\n  \"public_network_used\": false,\n  \"external_scanners_required\": false,\n  \"external_scanners_unavailable\": {},\n  \"passed\": {},\n  \"case_count\": {},\n  \"cases\": [{}],\n  \"exit_code\": {}\n}}",
            json_string(RELEASE_TARGET),
            json_string(RELEASE_CLAIM),
            json_string_array(&unavailable_scanners),
            passed,
            results.len(),
            case_json,
            exit_code
        );
    }

    let case_lines = results
        .iter()
        .map(|result| {
            format!(
                "case name={} category={} comparator={} expected_status={} actual_status={} passed={} reason_codes={:?}",
                result.name,
                result.category,
                result.comparator,
                result.expected_status,
                result.actual_status,
                result.passed,
                result.reason_codes
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere vm red-team-gate\nrelease_target={}\nrelease_claim={}\ngate_scope=fixture_safe_local_no_arbitrary_execution\npublic_network_used=false\nexternal_scanners_required=false\nexternal_scanners_unavailable={:?}\npassed={}\ncase_count={}\n{}\nexit_code={}",
        RELEASE_TARGET,
        RELEASE_CLAIM,
        unavailable_scanners,
        passed,
        results.len(),
        case_lines,
        exit_code
    )
}

