#[derive(Debug, Clone, PartialEq, Eq)]
struct ProtectSourceGate {
    rendered: String,
    blocked_output: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProtectPackageIdentityGate {
    rendered: String,
    blocked_output: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProtectLaunchGate {
    rendered: String,
    blocked_output: Option<String>,
}

fn render_protect_package_identity_gate(
    tool: &str,
    args: &[String],
    classification: &CommandClassification,
    workspace: &Option<String>,
    policy: &PolicyDocument,
) -> ProtectPackageIdentityGate {
    if !package_identity_gate_applies(classification.kind) {
        return ProtectPackageIdentityGate {
            rendered:
                "package_identity_status=skipped\npackage_identity_reason=not_install_workflow"
                    .to_string(),
            blocked_output: None,
        };
    }

    let requirement_files = command_requirement_file_args(args, classification.kind);
    if !requirement_files.is_empty() && workspace.is_none() {
        return ProtectPackageIdentityGate {
            rendered: String::new(),
            blocked_output: Some(render_requirements_workspace_required(
                &requirement_files,
                policy,
            )),
        };
    }

    let mut report = PackageIdentityReport::empty();
    if let Some(workspace) = workspace {
        report.merge(discover_package_identities_for_ecosystem(
            std::path::Path::new(workspace),
            package_identity_ecosystem_for_command(classification.kind),
        ));
        report.merge(command_requirement_file_identities(
            std::path::Path::new(workspace),
            &requirement_files,
        ));
    }
    report.merge(command_package_identities(tool, args, classification.kind));

    let rendered = render_package_identity_report(&report, policy);
    if package_identity_report_blocks(&report, policy) {
        ProtectPackageIdentityGate {
            rendered: String::new(),
            blocked_output: Some(rendered),
        }
    } else {
        ProtectPackageIdentityGate {
            rendered,
            blocked_output: None,
        }
    }
}

fn package_identity_gate_applies(kind: CommandKind) -> bool {
    matches!(
        kind,
        CommandKind::NpmInstall
            | CommandKind::NpmCi
            | CommandKind::NpmExec
            | CommandKind::PipInstall
            | CommandKind::PythonModulePipInstall
            | CommandKind::UvSync
            | CommandKind::UvPipInstall
    )
}

fn package_identity_ecosystem_for_command(kind: CommandKind) -> PackageIdentityEcosystem {
    match kind {
        CommandKind::NpmInstall | CommandKind::NpmCi | CommandKind::NpmExec => {
            PackageIdentityEcosystem::Npm
        }
        CommandKind::PipInstall
        | CommandKind::PythonModulePipInstall
        | CommandKind::UvSync
        | CommandKind::UvPipInstall => PackageIdentityEcosystem::Python,
        CommandKind::VersionProbe | CommandKind::Unknown => PackageIdentityEcosystem::Npm,
    }
}

fn package_identity_report_blocks(report: &PackageIdentityReport, policy: &PolicyDocument) -> bool {
    report.has_blocking_findings()
        || report.identities.iter().any(|identity| {
            evaluate_source_policy(
                &identity.name,
                policy_source_kind(identity.source_kind),
                &policy.namespace_rules,
                ExecutionMode::CiFailClosed,
            )
            .decision
                != PolicyDecision::Allow
        })
}

fn render_package_identity_report(
    report: &PackageIdentityReport,
    policy: &PolicyDocument,
) -> String {
    let parser_blocked = report.has_blocking_findings();
    let evaluations = report
        .identities
        .iter()
        .map(|identity| {
            (
                identity,
                evaluate_source_policy(
                    &identity.name,
                    policy_source_kind(identity.source_kind),
                    &policy.namespace_rules,
                    ExecutionMode::CiFailClosed,
                ),
            )
        })
        .collect::<Vec<_>>();
    let policy_blocked = evaluations
        .iter()
        .any(|(_, evaluation)| evaluation.decision != PolicyDecision::Allow);
    let status = if parser_blocked || policy_blocked {
        "blocked"
    } else {
        "ok"
    };
    let reason = if parser_blocked {
        "package_identity_manifest_blocked"
    } else if policy_blocked {
        evaluations
            .iter()
            .find(|(_, evaluation)| evaluation.decision != PolicyDecision::Allow)
            .map(|(_, evaluation)| evaluation.reason_code)
            .unwrap_or("package_identity_policy_blocked")
    } else if report.identities.is_empty() {
        "no_package_identities_discovered"
    } else {
        "package_identities_allowed"
    };
    let exit_code = if status == "blocked" {
        ExitCode::Deny.code()
    } else {
        ExitCode::Allow.code()
    };
    let finding_lines = report
        .findings
        .iter()
        .map(|finding| {
            format!(
                "package_identity_finding severity={:?} reason_code={} file={} detail=\"{}\"",
                finding.severity,
                finding.reason_code,
                redacted_scalar(&finding.file),
                redacted_scalar(&finding.detail)
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let identity_lines = evaluations
        .iter()
        .map(|(identity, evaluation)| {
            format!(
                "package_identity ecosystem={:?} source={:?} file={} package={} decision={:?} reason_code={}",
                identity.ecosystem,
                identity.source_kind,
                redacted_scalar(&identity.file),
                redacted_scalar(&identity.name),
                evaluation.decision,
                evaluation.reason_code
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "package_identity_status={status}\npackage_identity_reason={reason}\npackage_identity_policy_version={}\npackage_identity_files_scanned={}\npackage_identity_count={}\npackage_identity_blocking_findings={}\npackage_identity_exit_code={exit_code}{}{}{}{}",
        redacted_scalar(&policy.policy_version),
        report.files_scanned,
        report.identities.len(),
        parser_blocked || policy_blocked,
        if finding_lines.is_empty() { "" } else { "\n" },
        finding_lines,
        if identity_lines.is_empty() { "" } else { "\n" },
        identity_lines
    )
}

fn render_requirements_workspace_required(files: &[String], policy: &PolicyDocument) -> String {
    let file_lines = files
        .iter()
        .map(|file| {
            format!(
                "package_identity_finding severity=High reason_code=requirements_argv_workspace_required file={} detail=\"pip requirement or constraint file requires --workspace for safe inspection\"",
                redacted_scalar(file)
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "package_identity_status=blocked\npackage_identity_reason=requirements_argv_workspace_required\npackage_identity_policy_version={}\npackage_identity_files_scanned=0\npackage_identity_count=0\npackage_identity_blocking_findings=true\npackage_identity_exit_code={}{}{}",
        redacted_scalar(&policy.policy_version),
        ExitCode::Deny.code(),
        if file_lines.is_empty() { "" } else { "\n" },
        file_lines
    )
}

fn policy_source_kind(source_kind: PackageIdentitySourceKind) -> SourceKind {
    match source_kind {
        PackageIdentitySourceKind::PublicRegistry => SourceKind::Public,
        PackageIdentitySourceKind::DirectUrl => SourceKind::DirectUrl,
        PackageIdentitySourceKind::Git => SourceKind::Git,
        PackageIdentitySourceKind::LocalPath => SourceKind::LocalPath,
    }
}

fn command_package_identities(
    tool: &str,
    args: &[String],
    kind: CommandKind,
) -> PackageIdentityReport {
    let mut report = PackageIdentityReport::empty();
    match kind {
        CommandKind::NpmInstall | CommandKind::NpmExec => {
            for name in npm_package_arg_names(args) {
                report.push_identity(PackageIdentity {
                    ecosystem: PackageIdentityEcosystem::Npm,
                    source_kind: PackageIdentitySourceKind::PublicRegistry,
                    file: "<argv>".to_string(),
                    name,
                });
            }
        }
        CommandKind::PipInstall
        | CommandKind::PythonModulePipInstall
        | CommandKind::UvPipInstall => {
            for (name, source_kind) in pip_package_arg_entries(tool, args, kind) {
                report.push_identity(PackageIdentity {
                    ecosystem: PackageIdentityEcosystem::Python,
                    source_kind,
                    file: "<argv>".to_string(),
                    name,
                });
            }
        }
        CommandKind::NpmCi
        | CommandKind::UvSync
        | CommandKind::VersionProbe
        | CommandKind::Unknown => {}
    }
    report
}

fn command_requirement_file_identities(
    workspace: &std::path::Path,
    requirement_files: &[String],
) -> PackageIdentityReport {
    let mut report = PackageIdentityReport::empty();
    for relative in requirement_files {
        if matches!(
            relative.as_str(),
            "requirements.txt" | "requirements-dev.txt"
        ) {
            continue;
        }
        report.merge(discover_requirements_identities(workspace, relative));
    }
    report
}

fn command_requirement_file_args(args: &[String], kind: CommandKind) -> Vec<String> {
    if !matches!(
        kind,
        CommandKind::PipInstall | CommandKind::PythonModulePipInstall
    ) {
        return Vec::new();
    }
    let pip_args = if kind == CommandKind::PythonModulePipInstall && args.len() >= 2 {
        &args[2..]
    } else {
        args
    };
    pip_requirement_file_args(pip_args)
}

fn pip_requirement_file_args(args: &[String]) -> Vec<String> {
    let mut files = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if matches!(arg.as_str(), "-r" | "--requirement" | "-c" | "--constraint") {
            if let Some(value) = args.get(index + 1) {
                push_unique_string(&mut files, value);
            }
            index += 2;
            continue;
        }
        for prefix in ["--requirement=", "--constraint="] {
            if let Some(value) = arg.strip_prefix(prefix) {
                push_unique_string(&mut files, value);
            }
        }
        index += 1;
    }
    files
}

fn push_unique_string(values: &mut Vec<String>, value: &str) {
    if !values.iter().any(|existing| existing == value) {
        values.push(value.to_string());
    }
}

fn npm_package_arg_names(args: &[String]) -> Vec<String> {
    let Some(command_index) = args
        .iter()
        .position(|arg| matches!(arg.as_str(), "install" | "i" | "add" | "exec" | "x"))
    else {
        return Vec::new();
    };
    let mut names = Vec::new();
    let mut index = command_index + 1;
    while index < args.len() {
        let arg = &args[index];
        if arg == "--" {
            index += 1;
            continue;
        }
        if arg.starts_with('-') {
            index += if option_consumes_next(arg) { 2 } else { 1 };
            continue;
        }
        if let Some(name) = npm_package_name_from_spec(arg) {
            if !names.contains(&name) {
                names.push(name);
            }
        }
        index += 1;
    }
    names
}

fn pip_package_arg_entries(
    _tool: &str,
    args: &[String],
    kind: CommandKind,
) -> Vec<(String, PackageIdentitySourceKind)> {
    let pip_args = if kind == CommandKind::PythonModulePipInstall && args.len() >= 2 {
        &args[2..]
    } else {
        args
    };
    let Some(command_index) = pip_args.iter().position(|arg| arg == "install") else {
        return Vec::new();
    };
    let mut entries = Vec::new();
    let mut index = command_index + 1;
    while index < pip_args.len() {
        let arg = &pip_args[index];
        if arg == "--" {
            index += 1;
            continue;
        }
        if arg.starts_with('-') {
            index += if option_consumes_next(arg) { 2 } else { 1 };
            continue;
        }
        let report = extract_package_identities("<argv>", SourceFileKind::Requirements, arg);
        for identity in report.identities {
            let entry = (identity.name, identity.source_kind);
            if !entries.contains(&entry) {
                entries.push(entry);
            }
        }
        index += 1;
    }
    entries
}

fn option_consumes_next(arg: &str) -> bool {
    !arg.contains('=')
        && matches!(
            arg,
            "--registry"
                | "--userconfig"
                | "--globalconfig"
                | "--cache"
                | "--prefix"
                | "--index-url"
                | "-i"
                | "--extra-index-url"
                | "--find-links"
                | "-f"
                | "--requirement"
                | "-r"
                | "--constraint"
                | "-c"
                | "--python"
                | "--config-settings"
                | "-C"
        )
}

fn npm_package_name_from_spec(spec: &str) -> Option<String> {
    let spec = spec.trim();
    if spec.is_empty()
        || spec.starts_with("http://")
        || spec.starts_with("https://")
        || spec.starts_with("git+")
        || spec.starts_with("file:")
        || spec.starts_with("./")
        || spec.starts_with("../")
        || spec.starts_with('/')
        || spec.starts_with("github:")
        || spec.contains("://")
    {
        return None;
    }
    let candidate = if spec.starts_with('@') {
        let slash_index = spec.find('/')?;
        let rest = &spec[slash_index + 1..];
        let end = rest.find('@').map(|offset| slash_index + 1 + offset);
        &spec[..end.unwrap_or(spec.len())]
    } else {
        spec.split('@').next().unwrap_or(spec)
    };
    if valid_npm_package_arg_name(candidate) {
        Some(candidate.to_string())
    } else {
        None
    }
}

fn valid_npm_package_arg_name(value: &str) -> bool {
    if let Some((scope, name)) = value.split_once('/') {
        return scope.starts_with('@')
            && valid_npm_package_arg_segment(&scope[1..])
            && valid_npm_package_arg_segment(name)
            && !name.contains('/');
    }
    valid_npm_package_arg_segment(value)
}

fn valid_npm_package_arg_segment(value: &str) -> bool {
    !value.is_empty()
        && value
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-' | '~'))
}

fn render_protect_launch_gate(
    tool: &str,
    args: &[String],
    execute: bool,
    classification: &CommandClassification,
    workspace: Option<&str>,
    vault_origin: Option<&str>,
    audit_path: Option<&str>,
) -> ProtectLaunchGate {
    if !execute {
        return ProtectLaunchGate {
            rendered: "launch_plan_status=skipped\nlaunch_plan_reason=execution_not_requested"
                .to_string(),
            blocked_output: None,
        };
    }
    if classification.risk == WorkflowRisk::Low {
        return ProtectLaunchGate {
            rendered: "launch_plan_status=skipped\nlaunch_plan_reason=readonly_runner_path"
                .to_string(),
            blocked_output: None,
        };
    }

    let mut request = LaunchRequest::new(tool.to_string(), args.to_vec());
    request.execute_requested = execute;
    request.workspace = workspace.map(std::path::PathBuf::from);
    request.vault_origin = vault_origin.map(str::to_string);
    request.containment_proof = ContainmentProof::missing(ExecutionMode::CiFailClosed);
    request.egress_proof = EgressProof::missing();
    let plan = build_launch_plan(&request);
    let audit_status =
        render_audit_write_status("launch", audit_path, &launch_audit_record(&plan, execute));
    let launch_context_hash = plan.launch_context_hash.as_deref().unwrap_or("none");
    let source_scan_hash = plan.source_scan_hash.as_deref().unwrap_or("none");
    let rendered = format!(
        "launch_plan_status={}\nlaunch_plan_reason_codes={:?}\nlaunch_plan_context_hash={}\nlaunch_plan_source_scan_hash={}\nlaunch_plan_containment_proof_status={:?}\nlaunch_plan_containment_proof_subject={}\nlaunch_plan_containment_proof_provider_id={}\nlaunch_plan_containment_proof_mechanism={:?}\nlaunch_plan_containment_proof_trust={:?}\nlaunch_plan_containment_proof_expires_at={}\nlaunch_plan_containment_proof_reason={}\nlaunch_plan_egress_proof_status={:?}\nlaunch_plan_egress_proof_subject={}\nlaunch_plan_egress_proof_provider_id={}\nlaunch_plan_egress_proof_mechanism={:?}\nlaunch_plan_egress_proof_trust={:?}\nlaunch_plan_egress_proof_scope={:?}\nlaunch_plan_egress_proof_expires_at={}\nlaunch_plan_egress_proof_reason={}\nlaunch_plan_execution_allowed={}{}{}",
        match plan.status {
            LaunchStatus::Blocked => "blocked",
            LaunchStatus::Planned => "planned",
        },
        plan.reason_codes,
        redacted_scalar(launch_context_hash),
        redacted_scalar(source_scan_hash),
        plan.containment_proof.status(),
        redacted_scalar(&plan.containment_proof.subject().launch_id),
        redacted_scalar(&plan.containment_proof.provenance().provider_id),
        plan.containment_proof.provenance().mechanism,
        plan.containment_proof.provenance().trust,
        plan.containment_proof
            .provenance()
            .expires_at_unix_seconds,
        plan.containment_proof.reason_code(),
        plan.egress_proof.status(),
        redacted_scalar(&plan.egress_proof.subject().launch_id),
        redacted_scalar(&plan.egress_proof.provenance().provider_id),
        plan.egress_proof.provenance().mechanism,
        plan.egress_proof.provenance().trust,
        plan.egress_proof.policy_scope(),
        plan.egress_proof.provenance().expires_at_unix_seconds,
        plan.egress_proof.reason_code(),
        plan.execution_allowed,
        if audit_status.is_empty() { "" } else { "\n" },
        audit_status
    );
    if plan.status == LaunchStatus::Blocked {
        ProtectLaunchGate {
            rendered: String::new(),
            blocked_output: Some(rendered),
        }
    } else {
        ProtectLaunchGate {
            rendered,
            blocked_output: None,
        }
    }
}

fn render_protect_source_gate(
    tool: &str,
    args: &[String],
    kind: CommandKind,
    workspace: &Option<String>,
    vault_origin: Option<&str>,
) -> ProtectSourceGate {
    let Some(vault_origin) = vault_origin else {
        if workspace.is_some() {
            return ProtectSourceGate {
                rendered: String::new(),
                blocked_output: Some(
                    "source_scan_status=blocked\nsource_scan_reason=vault_origin_required"
                        .to_string(),
                ),
            };
        }
        return ProtectSourceGate {
            rendered:
                "source_scan_status=skipped\nsource_scan_reason=workspace_and_vault_origin_not_configured\nlaunch_context_status=skipped"
                    .to_string(),
            blocked_output: None,
        };
    };

    let context = match build_sanitized_context(tool, vault_origin) {
        Ok(context) => context,
        Err(error) => {
            return ProtectSourceGate {
                rendered: String::new(),
                blocked_output: Some(format!(
                    "source_scan_status=blocked\nsource_scan_reason=invalid_launch_context\n{}",
                    render_context_error_lines(tool, error)
                )),
            };
        }
    };
    let context_summary = render_context_summary(&context);

    let Some(workspace) = workspace else {
        return ProtectSourceGate {
            rendered: format!(
                "source_scan_status=skipped\nsource_scan_reason=workspace_not_configured\n{context_summary}"
            ),
            blocked_output: None,
        };
    };

    let workspace_path = std::path::Path::new(workspace);
    let mut report = scan_workspace(workspace_path, vault_origin);
    report.merge(command_requirement_file_source_scan(
        workspace_path,
        args,
        kind,
        vault_origin,
    ));
    let rendered_report = render_source_report(&report);
    if report.has_blocking_findings() {
        ProtectSourceGate {
            rendered: String::new(),
            blocked_output: Some(format!("{rendered_report}\n{context_summary}")),
        }
    } else {
        ProtectSourceGate {
            rendered: format!("{rendered_report}\n{context_summary}"),
            blocked_output: None,
        }
    }
}

fn command_requirement_file_source_scan(
    workspace: &std::path::Path,
    args: &[String],
    kind: CommandKind,
    vault_origin: &str,
) -> SourceScanReport {
    if !matches!(
        kind,
        CommandKind::PipInstall | CommandKind::PythonModulePipInstall
    ) {
        return SourceScanReport::empty();
    }
    let mut report = SourceScanReport::empty();
    for relative in command_requirement_file_args(args, kind) {
        if matches!(
            relative.as_str(),
            "requirements.txt" | "requirements-dev.txt"
        ) {
            continue;
        }
        report.merge(scan_requirements_path(workspace, &relative, vault_origin));
    }
    report
}

fn render_source_report(report: &SourceScanReport) -> String {
    let status = if report.has_blocking_findings() {
        "blocked"
    } else {
        "ok"
    };
    let exit_code = if report.has_blocking_findings() {
        ExitCode::Deny.code()
    } else {
        ExitCode::Allow.code()
    };
    let finding_lines = report
        .findings
        .iter()
        .map(|finding| {
            format!(
                "finding severity={:?} reason_code={} file={} detail=\"{}\"",
                finding.severity,
                finding.reason_code,
                redacted_scalar(&finding.file),
                redacted_scalar(&finding.detail)
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "source_scan_status={status}\nfiles_scanned={}\nfinding_count={}\nblocking_findings={}\nexit_code={exit_code}{}{}",
        report.files_scanned,
        report.findings.len(),
        report.has_blocking_findings(),
        if finding_lines.is_empty() { "" } else { "\n" },
        finding_lines
    )
}

fn render_context_summary(context: &SanitizedExecutionContext) -> String {
    let env_keys = context
        .env
        .iter()
        .map(|(key, _)| key.as_str())
        .collect::<Vec<_>>()
        .join(",");
    let vault_egress = vault_host_port(&context.vault_origin)
        .map(|host| evaluate_configured_vault_egress(&host, &host))
        .map(|decision| decision.reason_code.to_string())
        .unwrap_or_else(|| "egress_vault_origin_unparsed".to_string());
    format!(
        "launch_context_status=planned\nlaunch_context_tool={}\nlaunch_context_vault_origin={}\nlaunch_context_env_clear={}\nlaunch_context_env_keys={}\nlaunch_context_scrubbed_env_names={}\nlaunch_context_scrubbed_env_prefixes={}\nlaunch_context_config_path={}\nlaunch_context_config_bytes={}\nlaunch_context_egress_boundary_required={}\nlaunch_context_egress_probe={}\nlaunch_context_execution_enabled=false",
        redacted_scalar(&context.tool),
        redacted_scalar(&context.vault_origin),
        context.env_clear,
        env_keys,
        context.scrubbed_env_names.join(","),
        context.scrubbed_env_prefixes.join(","),
        redacted_scalar(&context.generated_config_path),
        context.generated_config_contents.len(),
        context.egress_boundary_required,
        vault_egress
    )
}

fn render_context_error_lines(tool: &str, error: ContextError) -> String {
    let reason = match error {
        ContextError::InvalidVaultOrigin(_) => "invalid_vault_origin",
        ContextError::UnsupportedTool(_) => "unsupported_tool",
    };
    format!(
        "status=error\nreason_code={reason}\ntool={}\nerror={}",
        redacted_scalar(tool),
        redacted_scalar(&format!("{error:?}"))
    )
}

fn render_execution_plan(tool: &str, args: &[String], execute: bool) -> String {
    let plan = plan_protected_execution(tool, args, execute);
    match plan.decision() {
        ExecutionDecision::ExecuteReadonly => match execute_readonly(&plan) {
            Ok(output) => format!(
                "execution_requested=true\nexecution_decision=execute_readonly\nexecution_reason={}\nexecution_status={:?}\nexecution_stdout={:?}\nexecution_stderr={:?}",
                plan.reason_code(),
                output.status_code,
                redacted_scalar(&output.stdout),
                redacted_scalar(&output.stderr)
            ),
            Err(error) => format!(
                "execution_requested=true\nexecution_decision=refuse\nexecution_reason=readonly_execution_failed\nexecution_error={}",
                redacted_scalar(&error.to_string())
            ),
        },
        ExecutionDecision::Refuse => format!(
            "execution_requested={execute}\nexecution_decision=refuse\nexecution_reason={}",
            plan.reason_code()
        ),
    }
}

fn render_config_check(path: &str) -> String {
    let contents = match std::fs::read_to_string(path) {
        Ok(contents) => contents,
        Err(error) => {
            return format!(
                "whoathere config check\nstatus=error\nreason_code=config_read_failed\npath={path}\nerror={error}"
            );
        }
    };
    match parse_config_kv(&contents) {
        Ok(config) => format!(
            "whoathere config check\nstatus=ok\npath={path}\nschema_version={}\nmode={:?}\noutage_behavior={:?}\ntelemetry_redacted_remote={}\nvault_url_set={}",
            config.schema_version,
            config.mode,
            config.outage_behavior,
            config.telemetry_redacted_remote,
            config.vault_url.is_some()
        ),
        Err(error) => format!(
            "whoathere config check\nstatus=error\nreason_code=config_invalid\npath={path}\nerror={error:?}"
        ),
    }
}

fn render_manifest_scan(kind: &str, path: &str) -> String {
    if !matches!(kind, "npm-package-json" | "pyproject" | "pyproject.toml") {
        return format!(
            "whoathere scan manifest\nstatus=error\nreason_code=unsupported_manifest_kind\nkind={kind}"
        );
    }

    let contents = match std::fs::read_to_string(path) {
        Ok(contents) => contents,
        Err(error) => {
            return format!(
                "whoathere scan manifest\nstatus=error\nreason_code=manifest_read_failed\npath={path}\nerror={error}"
            );
        }
    };

    let report = match kind {
        "npm-package-json" => scan_npm_package_json(&contents),
        "pyproject" | "pyproject.toml" => scan_pyproject_toml(&contents),
        _ => unreachable!("unsupported kind returned before file read"),
    };
    let finding_lines = report
        .findings
        .iter()
        .map(|finding| {
            format!(
                "finding severity={:?} reason_code={} detail=\"{}\"",
                finding.severity, finding.reason_code, finding.detail
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere scan manifest\nstatus=ok\nkind={kind}\npath={path}\npassed={}\nfinding_count={}\n{}",
        report.passed(),
        report.findings.len(),
        finding_lines
    )
}

fn render_scanners_list(json: bool) -> String {
    let inventory = scanner_inventory();
    let core_count = inventory
        .iter()
        .filter(|item| item.spec.role == ScannerExecutionRole::Core)
        .count();
    let core_available_count = inventory
        .iter()
        .filter(|item| item.spec.role == ScannerExecutionRole::Core && item.available)
        .count();
    let bootstrap = scanner_bootstrap_receipt_readiness(&inventory);
    let public_auto_trust_ready = bootstrap.public_auto_trust_ready;
    if json {
        let scanners_json = inventory
            .iter()
            .map(|item| {
                format!(
                    "{{\"name\": {}, \"role\": {}, \"available\": {}, \"path\": {}, \"version\": {}, \"evidence_role\": {}}}",
                    json_string(item.spec.name),
                    json_string(item.spec.role.as_str()),
                    item.available,
                    item.display_path
                        .as_deref()
                        .map(json_string)
                        .unwrap_or_else(|| "null".to_string()),
                    item.version
                        .as_deref()
                        .map(json_string)
                        .unwrap_or_else(|| "null".to_string()),
                    json_string(item.spec.evidence_role)
                )
            })
            .collect::<Vec<_>>()
            .join(", ");
        return format!(
            "{{\n  \"command\": \"whoathere scanners list\",\n  \"schema_version\": {},\n  \"core_scanner_count\": {},\n  \"core_scanner_available_count\": {},\n  \"bootstrap_receipt_present\": {},\n  \"bootstrap_receipt_path\": {},\n  \"bootstrap_receipt_valid\": {},\n  \"bootstrap_receipt_reason_codes\": {},\n  \"scanner_public_package_auto_trust_ready\": {},\n  \"scanners\": [{}],\n  \"exit_code\": 0\n}}",
            json_string(EXTERNAL_SCANNER_RUN_SCHEMA),
            core_count,
            core_available_count,
            bootstrap.present,
            json_string(&redacted_path_string(&scanner_bootstrap_receipt_path())),
            bootstrap.valid,
            json_string_array(&bootstrap.reason_codes),
            public_auto_trust_ready,
            scanners_json
        );
    }
    let rows = inventory
        .iter()
        .map(|item| {
            format!(
                "scanner={} role={} available={} path={} version={} evidence_role=\"{}\"",
                item.spec.name,
                item.spec.role.as_str(),
                item.available,
                item.display_path.as_deref().unwrap_or("none"),
                item.version.as_deref().unwrap_or("unknown"),
                item.spec.evidence_role
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere scanners list\nschema_version={}\ncore_scanner_count={}\ncore_scanner_available_count={}\nbootstrap_receipt_present={}\nbootstrap_receipt_path={}\nbootstrap_receipt_valid={}\nbootstrap_receipt_reason_codes={:?}\nscanner_public_package_auto_trust_ready={}\n{}\nexit_code=0",
        EXTERNAL_SCANNER_RUN_SCHEMA,
        core_count,
        core_available_count,
        bootstrap.present,
        redacted_path_string(&scanner_bootstrap_receipt_path()),
        bootstrap.valid,
        bootstrap.reason_codes,
        public_auto_trust_ready,
        rows
    )
}

struct ScannerBootstrapReceiptReadiness {
    present: bool,
    valid: bool,
    public_auto_trust_ready: bool,
    reason_codes: Vec<String>,
}

fn scanner_bootstrap_receipt_readiness(
    inventory: &[ExternalScannerInventoryItem],
) -> ScannerBootstrapReceiptReadiness {
    let core_count = inventory
        .iter()
        .filter(|item| item.spec.role == ScannerExecutionRole::Core)
        .count();
    let core_available_count = inventory
        .iter()
        .filter(|item| item.spec.role == ScannerExecutionRole::Core && item.available)
        .count();
    let path = scanner_bootstrap_receipt_path();
    if !path.is_file() {
        return ScannerBootstrapReceiptReadiness {
            present: false,
            valid: false,
            public_auto_trust_ready: false,
            reason_codes: vec!["scanner_bootstrap_receipt_missing".to_string()],
        };
    }
    let contents = match std::fs::read_to_string(&path) {
        Ok(contents) => contents,
        Err(_) => {
            return ScannerBootstrapReceiptReadiness {
                present: true,
                valid: false,
                public_auto_trust_ready: false,
                reason_codes: vec!["scanner_bootstrap_receipt_unreadable".to_string()],
            };
        }
    };
    let mut reason_codes = validate_scanner_bootstrap_receipt(&contents, inventory);
    if core_available_count != core_count {
        reason_codes.push("scanner_bootstrap_current_core_scanners_missing".to_string());
    }
    reason_codes.sort();
    reason_codes.dedup();
    let valid = reason_codes.is_empty();
    ScannerBootstrapReceiptReadiness {
        present: true,
        valid,
        public_auto_trust_ready: valid && core_count > 0 && core_available_count == core_count,
        reason_codes,
    }
}

fn validate_scanner_bootstrap_receipt(
    contents: &str,
    inventory: &[ExternalScannerInventoryItem],
) -> Vec<String> {
    let mut reason_codes = Vec::new();
    let expected_core_count = inventory
        .iter()
        .filter(|item| item.spec.role == ScannerExecutionRole::Core)
        .count();
    if json_extract_string_field(contents, "schema_version").as_deref()
        != Some("whoathere.scanner_bootstrap.v1")
    {
        reason_codes.push("scanner_bootstrap_receipt_schema_invalid".to_string());
    }
    if json_extract_string_field(contents, "created_at")
        .as_deref()
        .unwrap_or("")
        .trim()
        .is_empty()
    {
        reason_codes.push("scanner_bootstrap_created_at_missing".to_string());
    }
    match json_extract_u64_field(contents, "core_scanner_count") {
        Some(count) if count as usize == expected_core_count => {}
        Some(_) => reason_codes.push("scanner_bootstrap_core_count_mismatch".to_string()),
        None => reason_codes.push("scanner_bootstrap_core_count_missing".to_string()),
    }
    match json_extract_u64_field(contents, "core_scanner_ready_count") {
        Some(count) if count as usize == expected_core_count => {}
        Some(_) => reason_codes.push("scanner_bootstrap_core_ready_count_mismatch".to_string()),
        None => reason_codes.push("scanner_bootstrap_core_ready_count_missing".to_string()),
    }
    if json_extract_bool_field(contents, "scanner_public_package_auto_trust_ready") != Some(true) {
        reason_codes.push("scanner_bootstrap_ready_flag_not_true".to_string());
    }
    let records = json_extract_object_array(contents, "scanners");
    for item in inventory
        .iter()
        .filter(|item| item.spec.role == ScannerExecutionRole::Core)
    {
        let expected = item.spec.name;
        let Some(record) = records
            .iter()
            .find(|record| json_extract_string_field(record, "name").as_deref() == Some(expected))
        else {
            reason_codes.push("scanner_bootstrap_core_record_missing".to_string());
            continue;
        };
        if !item.available {
            reason_codes.push("scanner_bootstrap_current_core_scanner_unavailable".to_string());
        }
        if json_extract_string_field(record, "role").as_deref() != Some("core") {
            reason_codes.push("scanner_bootstrap_core_record_role_invalid".to_string());
        }
        if !matches!(
            json_extract_string_field(record, "status").as_deref(),
            Some("available" | "installed" | "uvx_available")
        ) {
            reason_codes.push("scanner_bootstrap_core_record_not_ready".to_string());
        }
        match (
            json_extract_string_field(record, "version"),
            item.version.as_deref(),
        ) {
            (Some(record_version), Some(current_version))
                if record_version.trim() == current_version.trim() => {}
            (Some(_), Some(_)) => {
                reason_codes.push("scanner_bootstrap_core_record_version_mismatch".to_string())
            }
            (None, _) => {
                reason_codes.push("scanner_bootstrap_core_record_version_missing".to_string())
            }
            _ => {}
        }
    }
    reason_codes
}

fn render_scanners_bootstrap_plan(json: bool) -> String {
    let specs = external_scanner_specs();
    let cache_dir = scanner_bootstrap_receipt_path()
        .parent()
        .map(redacted_path_string)
        .unwrap_or_else(|| "<whoathere-scanner-cache>".to_string());
    if json {
        let scanner_json = specs
            .iter()
            .map(|spec| {
                let install = scanner_install_hint(spec.name);
                format!(
                    "{{\"name\": {}, \"role\": {}, \"install_hint\": {}, \"evidence_role\": {}}}",
                    json_string(spec.name),
                    json_string(spec.role.as_str()),
                    json_string(install),
                    json_string(spec.evidence_role)
                )
            })
            .collect::<Vec<_>>()
            .join(", ");
        return format!(
            "{{\n  \"command\": \"whoathere scanners bootstrap-plan\",\n  \"schema_version\": {},\n  \"cache_dir\": {},\n  \"bootstrap_script\": \"scripts/whoathere-bootstrap-scanners.sh\",\n  \"mutation\": false,\n  \"scanners\": [{}],\n  \"exit_code\": 0\n}}",
            json_string(EXTERNAL_SCANNER_RUN_SCHEMA),
            json_string(&cache_dir),
            scanner_json
        );
    }
    let rows = specs
        .iter()
        .map(|spec| {
            format!(
                "scanner={} role={} install_hint=\"{}\" evidence_role=\"{}\"",
                spec.name,
                spec.role.as_str(),
                scanner_install_hint(spec.name),
                spec.evidence_role
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere scanners bootstrap-plan\nschema_version={}\ncache_dir={}\nbootstrap_script=scripts/whoathere-bootstrap-scanners.sh\nmutation=false\n{}\nexit_code=0",
        EXTERNAL_SCANNER_RUN_SCHEMA,
        cache_dir,
        rows
    )
}

fn render_scanners_run(
    workspace: Option<&str>,
    ecosystem: Option<&str>,
    state_dir: Option<&str>,
    timeout_seconds: Option<u64>,
    execute: bool,
    json: bool,
) -> String {
    let Some(workspace) = workspace else {
        return scanner_misuse("scanner_workspace_required", json);
    };
    let ecosystem_value = ecosystem.unwrap_or("auto");
    let ecosystem = match ScannerEcosystem::parse(ecosystem_value) {
        Some(parsed) => parsed,
        None => return scanner_misuse("scanner_ecosystem_invalid", json),
    };
    let timeout = timeout_seconds.unwrap_or(120).clamp(1, 300);
    let workspace_path = Path::new(workspace);
    let summary = if execute {
        run_external_scanners(workspace_path, ecosystem, timeout, true)
    } else {
        plan_external_scanner_run(workspace_path, ecosystem)
    };
    let config = state_dir.map(|state_dir| macos_vm_config(Some(state_dir), None, None));
    render_scanner_run_summary(
        &summary,
        json,
        config.as_ref().map(|config| config.state_dir.as_path()),
    )
}

fn scanner_misuse(reason_code: &str, json: bool) -> String {
    if json {
        return format!(
            "{{\n  \"command\": \"whoathere scanners run\",\n  \"schema_version\": {},\n  \"status\": \"error\",\n  \"reason_code\": {},\n  \"exit_code\": {}\n}}",
            json_string(EXTERNAL_SCANNER_RUN_SCHEMA),
            json_string(reason_code),
            ExitCode::Misuse.code()
        );
    }
    format!(
        "whoathere scanners run\nschema_version={}\nstatus=error\nreason_code={reason_code}\nexit_code={}",
        EXTERNAL_SCANNER_RUN_SCHEMA,
        ExitCode::Misuse.code()
    )
}

fn render_scanner_run_summary(
    summary: &ExternalScannerRunSummary,
    json: bool,
    state_dir: Option<&Path>,
) -> String {
    let exit_code = if !summary.execute_requested || summary.scanner_clean {
        ExitCode::Allow.code()
    } else {
        ExitCode::Deny.code()
    };
    let created_at_unix_seconds = current_unix_seconds();
    let decision_summary = scanner_run_decision_summary(summary);
    let host_effect = scanner_run_host_effect(summary);
    let recommended_actions = scanner_run_recommended_actions(summary);
    if json {
        let records_json = summary
            .records
            .iter()
            .map(render_scanner_record_json)
            .collect::<Vec<_>>()
            .join(", ");
        let unsigned = format!(
            "{{\n  \"command\": \"whoathere scanners run\",\n  \"schema_version\": {},\n  \"created_at_unix_seconds\": {},\n  \"workspace\": \"<workspace>\",\n  \"workspace_sha256\": {},\n  \"workspace_kind\": {},\n  \"requested_ecosystem\": {},\n  \"effective_ecosystem\": {},\n  \"execute_requested\": {},\n  \"timeout_seconds\": {},\n  \"scanner_clean\": {},\n  \"decision_summary\": {},\n  \"host_effect\": {},\n  \"recommended_actions\": {},\n  \"core_scanner_count\": {},\n  \"core_scanner_runnable_count\": {},\n  \"reason_codes\": {},\n  \"records\": [{}],\n  \"exit_code\": {}\n}}",
            json_string(summary.schema_version),
            created_at_unix_seconds,
            json_string(&summary.workspace_sha256),
            json_string(&summary.workspace_kind),
            json_string(summary.requested_ecosystem.as_str()),
            json_string(summary.effective_ecosystem.as_str()),
            summary.execute_requested,
            summary.timeout_seconds,
            summary.scanner_clean,
            json_string(&decision_summary),
            json_string(&host_effect),
            json_string_array(&recommended_actions),
            summary.core_scanner_count,
            summary.core_scanner_runnable_count,
            json_string_array(&summary.reason_codes),
            records_json,
            exit_code
        );
        if summary.execute_requested {
            if let Some(state_dir) = state_dir {
                if let Ok(signed) = sign_scanner_receipt_contents(state_dir, &unsigned) {
                    return signed;
                }
            }
        }
        return unsigned;
    }
    let records = summary
        .records
        .iter()
        .map(render_scanner_record_text)
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere scanners run\nschema_version={}\ncreated_at_unix_seconds={}\nworkspace=<workspace>\nworkspace_sha256={}\nworkspace_kind={}\nrequested_ecosystem={}\neffective_ecosystem={}\nexecute_requested={}\ntimeout_seconds={}\nscanner_clean={}\ndecision_summary={}\nhost_effect={}\nrecommended_actions={:?}\ncore_scanner_count={}\ncore_scanner_runnable_count={}\nreason_codes={:?}\n{}\nexit_code={}",
        summary.schema_version,
        created_at_unix_seconds,
        summary.workspace_sha256,
        summary.workspace_kind,
        summary.requested_ecosystem.as_str(),
        summary.effective_ecosystem.as_str(),
        summary.execute_requested,
        summary.timeout_seconds,
        summary.scanner_clean,
        decision_summary,
        host_effect,
        recommended_actions,
        summary.core_scanner_count,
        summary.core_scanner_runnable_count,
        summary.reason_codes,
        records,
        exit_code
    )
}

fn scanner_run_decision_summary(summary: &ExternalScannerRunSummary) -> String {
    if !summary.execute_requested {
        return "Scanner execution was not requested. This is a command plan only and cannot be used as clean package evidence.".to_string();
    }
    if summary.scanner_clean {
        format!(
            "{} core scanner(s) ran or were not applicable, and no scanner findings were observed. This is useful evidence, not proof the package is safe.",
            summary.core_scanner_runnable_count
        )
    } else {
        "One or more scanners reported findings, errors, timeouts, or unavailable required evidence. Do not use this as clean package evidence.".to_string()
    }
}

fn scanner_run_host_effect(summary: &ExternalScannerRunSummary) -> String {
    if summary.execute_requested {
        "host_scanner_processes_spawned_raw_output_hashed_no_package_manager_install_no_package_code_intentionally_executed"
            .to_string()
    } else {
        "dry_run_no_scanner_processes_spawned_no_package_manager_install_no_package_code_executed"
            .to_string()
    }
}

fn scanner_run_recommended_actions(summary: &ExternalScannerRunSummary) -> Vec<String> {
    let mut actions = Vec::new();
    if !summary.execute_requested {
        actions.push(
            "Rerun with --execute to produce scanner evidence that package-risk can consider."
                .to_string(),
        );
    } else if summary.scanner_clean {
        actions.push(
            "Pass this scanner receipt to whoathere package-risk assess with --scanner-receipt."
                .to_string(),
        );
    } else {
        actions.push(
            "Review scanner records and keep package execution inside the VM until findings or scanner failures are resolved."
                .to_string(),
        );
    }
    if summary
        .reason_codes
        .iter()
        .any(|reason| reason.contains("timed_out"))
    {
        actions.push(
            "Increase --timeout-seconds only if the scanner is trusted and the workspace size warrants it."
                .to_string(),
        );
    }
    if summary.reason_codes.iter().any(|reason| {
        reason.contains("unavailable")
            || reason.contains("not_found")
            || reason.contains("spawn_failed")
    }) {
        actions.push(
            "Run whoathere scanners bootstrap-plan or scripts/whoathere-bootstrap-scanners.sh to install missing scanners."
                .to_string(),
        );
    }
    actions.sort();
    actions.dedup();
    actions
}

fn render_scanner_record_json(record: &ExternalScannerRunRecord) -> String {
    format!(
        "{{\"schema_version\": {}, \"scanner\": {}, \"role\": {}, \"ecosystem\": {}, \"status\": {}, \"path\": {}, \"executable_sha256\": {}, \"argv\": {}, \"exit_code\": {}, \"elapsed_ms\": {}, \"timed_out\": {}, \"stdout_sha256\": {}, \"stderr_sha256\": {}, \"stdout_bytes\": {}, \"stderr_bytes\": {}, \"finding_count\": {}, \"reason_codes\": {}}}",
        json_string(record.schema_version),
        json_string(&record.scanner),
        json_string(record.role.as_str()),
        json_string(record.ecosystem.as_str()),
        json_string(record.status.as_str()),
        record
            .display_path
            .as_deref()
            .map(json_string)
            .unwrap_or_else(|| "null".to_string()),
        json_option_string(record.executable_sha256.as_deref()),
        json_string_array(&record.argv),
        record
            .exit_code
            .map(|code| code.to_string())
            .unwrap_or_else(|| "null".to_string()),
        record.elapsed_ms,
        record.timed_out,
        record
            .stdout_sha256
            .as_deref()
            .map(json_string)
            .unwrap_or_else(|| "null".to_string()),
        record
            .stderr_sha256
            .as_deref()
            .map(json_string)
            .unwrap_or_else(|| "null".to_string()),
        record.stdout_bytes,
        record.stderr_bytes,
        record.finding_count,
        json_string_array(&record.reason_codes)
    )
}

fn render_scanner_record_text(record: &ExternalScannerRunRecord) -> String {
    format!(
        "scanner_result scanner={} role={} ecosystem={} status={} path={} executable_sha256={} argv={:?} exit_code={} elapsed_ms={} timed_out={} stdout_sha256={} stderr_sha256={} stdout_bytes={} stderr_bytes={} finding_count={} reason_codes={:?}",
        record.scanner,
        record.role.as_str(),
        record.ecosystem.as_str(),
        record.status.as_str(),
        record.display_path.as_deref().unwrap_or("none"),
        record.executable_sha256.as_deref().unwrap_or("none"),
        record.argv,
        record
            .exit_code
            .map(|code| code.to_string())
            .unwrap_or_else(|| "null".to_string()),
        record.elapsed_ms,
        record.timed_out,
        record.stdout_sha256.as_deref().unwrap_or("none"),
        record.stderr_sha256.as_deref().unwrap_or("none"),
        record.stdout_bytes,
        record.stderr_bytes,
        record.finding_count,
        record.reason_codes
    )
}

fn scanner_install_hint(name: &str) -> &'static str {
    match name {
        "guarddog" => "uv tool install guarddog, or use uvx guarddog",
        "pip-audit" => "uv tool install pip-audit, or use uvx pip-audit",
        "osv-scanner" => "brew install osv-scanner, or download GitHub release",
        "syft" => "brew install syft, or download GitHub release",
        "grype" => "brew install grype, or download GitHub release",
        "trivy" => "brew install trivy, or download GitHub release",
        "scorecard" => "brew install scorecard, or download GitHub release",
        _ => "install scanner on PATH",
    }
}

fn redacted_path_string(path: &Path) -> String {
    let value = path.display().to_string();
    if value.contains(".whoathere/scanners") {
        return "<whoathere-scanner-cache>".to_string();
    }
    if value.contains("/Users/") {
        return "<redacted-path>".to_string();
    }
    value
}

const PACKAGE_RISK_ASSESSMENT_SCHEMA: &str = "whoathere.package_risk_assessment.v2";
const PACKAGE_RISK_STORE_SCHEMA: &str = "whoathere.package_risk_store_record.v2";
const PACKAGE_RISK_RECEIPT_AUTH_SCHEMA: &str = "whoathere.package_risk_receipt_auth.v1";
const SCANNER_RECEIPT_AUTH_SCHEMA: &str = "whoathere.scanner_receipt_auth.v1";
const PACKAGE_ARTIFACT_REVIEW_SCHEMA: &str = "whoathere.local_artifact_review.v1";
const PACKAGE_RISK_COOLDOWN_DAYS: u64 = 7;
const PACKAGE_RISK_RECEIPT_MAX_AGE_SECONDS: u64 = 24 * 60 * 60;
const PACKAGE_RISK_RECEIPT_FUTURE_SKEW_SECONDS: u64 = 5 * 60;
const PACKAGE_ARTIFACT_REVIEW_OUTPUT_LIMIT_BYTES: u64 = 512 * 1024;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LocalArtifactReviewStatus {
    NotRequested,
    Passed,
    Findings,
    NotApplicable,
    Unavailable,
    Error,
    TimedOut,
}

impl LocalArtifactReviewStatus {
    fn as_str(self) -> &'static str {
        match self {
            Self::NotRequested => "not_requested",
            Self::Passed => "passed",
            Self::Findings => "findings",
            Self::NotApplicable => "not_applicable",
            Self::Unavailable => "unavailable",
            Self::Error => "error",
            Self::TimedOut => "timed_out",
        }
    }

    fn blocks_auto_sync(self) -> bool {
        matches!(
            self,
            Self::Findings | Self::Unavailable | Self::Error | Self::TimedOut
        )
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LocalArtifactReviewEvidence {
    requested: bool,
    provider: String,
    model: Option<String>,
    status: LocalArtifactReviewStatus,
    prompt_sha256: Option<String>,
    output_sha256: Option<String>,
    elapsed_ms: Option<u128>,
    reason_codes: Vec<String>,
}

impl LocalArtifactReviewEvidence {
    fn not_requested(provider: String, model: Option<String>) -> Self {
        Self {
            requested: false,
            provider,
            model,
            status: LocalArtifactReviewStatus::NotRequested,
            prompt_sha256: None,
            output_sha256: None,
            elapsed_ms: None,
            reason_codes: vec!["artifact_review_not_requested".to_string()],
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PackageRiskScannerEvidence {
    requested: bool,
    applied: bool,
    receipt_path: Option<String>,
    scanner_clean: Option<bool>,
    status: String,
    reason_codes: Vec<String>,
}

impl PackageRiskScannerEvidence {
    fn not_requested() -> Self {
        Self {
            requested: false,
            applied: false,
            receipt_path: None,
            scanner_clean: None,
            status: "not_requested".to_string(),
            reason_codes: vec!["scanner_receipt_not_requested".to_string()],
        }
    }

    fn blocks_auto_sync(&self) -> bool {
        self.scanner_clean != Some(true)
    }

    fn clean_for_auto_sync(&self) -> bool {
        self.scanner_clean == Some(true)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PackageRiskEcosystem {
    Auto,
    Npm,
    Pypi,
    Uv,
}

impl PackageRiskEcosystem {
    fn parse(value: &str) -> Option<Self> {
        match value {
            "auto" => Some(Self::Auto),
            "npm" => Some(Self::Npm),
            "pypi" | "pip" | "python" => Some(Self::Pypi),
            "uv" => Some(Self::Uv),
            _ => None,
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::Npm => "npm",
            Self::Pypi => "pypi",
            Self::Uv => "uv",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PackageRiskVerdict {
    AutoSyncCandidate,
    ManualReview,
    Deny,
}

impl PackageRiskVerdict {
    fn as_str(self) -> &'static str {
        match self {
            Self::AutoSyncCandidate => "auto_sync_candidate",
            Self::ManualReview => "manual_review",
            Self::Deny => "deny",
        }
    }

    fn exit_code(self) -> i32 {
        match self {
            Self::AutoSyncCandidate => ExitCode::Allow.code(),
            Self::ManualReview => ExitCode::ManualReview.code(),
            Self::Deny => ExitCode::Deny.code(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PackageRiskSubject {
    ecosystem: PackageRiskEcosystem,
    package_name: String,
    requested_spec: String,
    resolved_version: Option<String>,
    source_kind: String,
    package_class: PackageClass,
    /// A deterministic snapshot fingerprint for legacy workspace admission.
    /// This is never an original package-artifact digest.
    workspace_subject_fingerprint: String,
    pinned: bool,
    publish_age_days: Option<u64>,
    reputation_status: String,
    indicators: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PackageRiskAssessment {
    ecosystem: PackageRiskEcosystem,
    package_name: String,
    requested_spec: String,
    resolved_version: Option<String>,
    selected_version: Option<String>,
    source_kind: String,
    package_class: PackageClass,
    workspace_subject_fingerprint: String,
    pinned: bool,
    last_known_good_version: Option<String>,
    last_known_good_subject_fingerprint: Option<String>,
    last_known_good_used: bool,
    publish_age_days: Option<u64>,
    freshness_allowed: bool,
    diff_clean_or_baseline_absent: bool,
    reputation_status: String,
    scanner_evidence: PackageRiskScannerEvidence,
    artifact_review: LocalArtifactReviewEvidence,
    indicators: Vec<String>,
    verdict: PackageRiskVerdict,
    reason_codes: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PackageRiskMemoryRecord {
    record_kind: String,
    ecosystem: PackageRiskEcosystem,
    package_name: String,
    requested_spec: String,
    resolved_version: Option<String>,
    selected_version: Option<String>,
    source_kind: String,
    package_class: String,
    workspace_subject_fingerprint: String,
    verdict: String,
    approved: bool,
    created_at_unix_seconds: u64,
    receipt_id: String,
    reason_codes: Vec<String>,
    diff_clean_or_baseline_absent: bool,
    freshness_allowed: bool,
    artifact_review_status: String,
    artifact_review_reason_codes: Vec<String>,
    scanner_evidence_status: String,
    scanner_clean: Option<bool>,
    scanner_evidence_reason_codes: Vec<String>,
}

const INTAKE_ASSESSMENT_SCHEMA: &str = "whoathere.intake_assessment.v1";

struct IntakeAssessArgs<'a> {
    workspace: Option<&'a str>,
    ecosystem: Option<&'a str>,
    state_dir: Option<&'a str>,
    helper_path: Option<&'a str>,
    scanner_receipt: Option<&'a str>,
    execute: bool,
    json: bool,
    ai_review: bool,
    ai_provider: Option<&'a str>,
    ai_model: Option<&'a str>,
    ai_timeout_seconds: Option<u64>,
    timeout_seconds: Option<u64>,
    tool: &'a str,
    args: &'a [String],
}

fn render_intake_assess(args: IntakeAssessArgs<'_>) -> String {
    let Some(workspace) = args.workspace else {
        return intake_assess_error("intake_workspace_required", args.json);
    };
    if !Path::new(workspace).is_dir() {
        return intake_assess_error("intake_workspace_not_directory", args.json);
    }
    if !matches!(args.tool, "npm" | "pip" | "uv") {
        return intake_assess_error("intake_tool_unsupported", args.json);
    }
    let package_ecosystem = match args.ecosystem {
        Some(value) => match PackageRiskEcosystem::parse(value) {
            Some(parsed) => parsed.as_str().to_string(),
            None => return intake_assess_error("intake_ecosystem_invalid", args.json),
        },
        None => intake_package_ecosystem_for_tool(args.tool).to_string(),
    };

    let package_risk = evaluate_command(Command::PackageRiskAssess {
        workspace: Some(workspace.to_string()),
        ecosystem: Some(package_ecosystem.clone()),
        state_dir: args.state_dir.map(ToString::to_string),
        scanner_receipt: args.scanner_receipt.map(ToString::to_string),
        ai_review: args.ai_review,
        ai_provider: args.ai_provider.map(ToString::to_string),
        ai_model: args.ai_model.map(ToString::to_string),
        ai_timeout_seconds: args.ai_timeout_seconds,
        json: true,
    });
    let vm_detonation = evaluate_command(Command::VmDetonate {
        tool: args.tool.to_string(),
        args: args.args.to_vec(),
        execute: args.execute,
        sync_back: false,
        state_dir: args.state_dir.map(ToString::to_string),
        helper_path: args.helper_path.map(ToString::to_string),
        workspace: Some(workspace.to_string()),
        package_risk_receipt: None,
        fixture: None,
        timeout_seconds: args.timeout_seconds,
        json: true,
    });

    let vm_verdict = json_extract_string_field(&vm_detonation.output, "verdict");
    let vm_sync_back_enabled =
        json_extract_bool_field(&vm_detonation.output, "sync_back_enabled").unwrap_or(true);
    let vm_dynamic_clean_evidence = args.execute
        && vm_detonation.exit_code == ExitCode::Allow.code()
        && !vm_sync_back_enabled
        && matches!(vm_verdict.as_deref(), Some("helper_observed_clean"));

    let mut reason_codes = Vec::new();
    reason_codes.push("intake_sync_back_disabled".to_string());
    if args.ai_review {
        reason_codes.push("intake_ai_review_requested".to_string());
    } else {
        reason_codes.push("intake_ai_review_not_requested".to_string());
    }
    if args.scanner_receipt.is_some() {
        reason_codes.push("intake_scanner_receipt_requested".to_string());
    } else {
        reason_codes.push("intake_scanner_receipt_not_requested".to_string());
    }
    if !args.execute {
        reason_codes.push("intake_vm_execute_required".to_string());
    }
    match package_risk.exit_code {
        code if code == ExitCode::Allow.code() => {
            reason_codes.push("intake_package_risk_clean".to_string())
        }
        code if code == ExitCode::Deny.code() => {
            reason_codes.push("intake_package_risk_denied".to_string())
        }
        code if code == ExitCode::ManualReview.code() => {
            reason_codes.push("intake_package_risk_manual_review".to_string())
        }
        _ => reason_codes.push("intake_package_risk_error".to_string()),
    }
    if args.execute {
        match vm_detonation.exit_code {
            code if code == ExitCode::Allow.code() => {
                if vm_dynamic_clean_evidence {
                    reason_codes.push("intake_vm_dynamic_clean_observed".to_string());
                } else {
                    reason_codes.push("intake_vm_dynamic_clean_evidence_missing".to_string());
                }
            }
            code if code == ExitCode::Deny.code() || code == ExitCode::ManualReview.code() => {
                reason_codes.push("intake_vm_detonation_not_clean".to_string())
            }
            _ => reason_codes.push("intake_vm_detonation_error".to_string()),
        }
    }
    if vm_sync_back_enabled {
        reason_codes.push("intake_vm_sync_back_unexpected".to_string());
    }
    reason_codes = sorted_unique(reason_codes);

    let package_risk_error = !matches!(
        package_risk.exit_code,
        code if code == ExitCode::Allow.code()
            || code == ExitCode::Deny.code()
            || code == ExitCode::ManualReview.code()
    );
    let vm_error = args.execute
        && !matches!(
            vm_detonation.exit_code,
            code if code == ExitCode::Allow.code()
                || code == ExitCode::Deny.code()
                || code == ExitCode::ManualReview.code()
        );
    let hard_deny = package_risk.exit_code == ExitCode::Deny.code()
        || vm_detonation.exit_code == ExitCode::Deny.code();
    let final_exit_code = if package_risk_error || vm_error {
        if package_risk.exit_code == ExitCode::Misuse.code()
            || vm_detonation.exit_code == ExitCode::Misuse.code()
        {
            ExitCode::Misuse.code()
        } else {
            ExitCode::InternalError.code()
        }
    } else if hard_deny {
        ExitCode::Deny.code()
    } else if package_risk.exit_code == ExitCode::Allow.code() && vm_dynamic_clean_evidence {
        ExitCode::Allow.code()
    } else {
        ExitCode::ManualReview.code()
    };
    let verdict = if final_exit_code == ExitCode::Allow.code() {
        "observed_clean_no_sync"
    } else if !args.execute {
        "dry_run_execute_required"
    } else if hard_deny {
        "deny"
    } else if package_risk_error || vm_error {
        "error_fail_closed"
    } else if !vm_dynamic_clean_evidence {
        "manual_review_dynamic_evidence_missing"
    } else {
        "manual_review"
    };

    let redacted_args = args
        .args
        .iter()
        .map(|arg| redacted_scalar(arg))
        .collect::<Vec<_>>();
    if args.json {
        return format!(
            "{{\n  \"command\": \"whoathere intake assess\",\n  \"schema_version\": {},\n  \"workspace\": {},\n  \"package_ecosystem\": {},\n  \"tool\": {},\n  \"argv\": {},\n  \"execute_requested\": {},\n  \"sync_back_enabled\": false,\n  \"ai_review_requested\": {},\n  \"scanner_receipt_requested\": {},\n  \"verdict\": {},\n  \"reason_codes\": {},\n  \"exit_code\": {},\n  \"package_risk_exit_code\": {},\n  \"vm_detonation_exit_code\": {},\n  \"package_risk\": {},\n  \"vm_detonation\": {}\n}}",
            json_string(INTAKE_ASSESSMENT_SCHEMA),
            json_string(&redacted_scalar(workspace)),
            json_string(&package_ecosystem),
            json_string(args.tool),
            json_string_array(&redacted_args),
            args.execute,
            args.ai_review,
            args.scanner_receipt.is_some(),
            json_string(verdict),
            json_string_array(&reason_codes),
            final_exit_code,
            package_risk.exit_code,
            vm_detonation.exit_code,
            json_embedded_report(&package_risk.output),
            json_embedded_report(&vm_detonation.output)
        );
    }

    format!(
        "whoathere intake assess\nschema_version={}\nfinal_exit_code={}\nworkspace={}\npackage_ecosystem={}\ntool={}\nargv={:?}\nexecute_requested={}\nsync_back_enabled=false\nai_review_requested={}\nscanner_receipt_requested={}\nverdict={}\nreason_codes={:?}\npackage_risk_exit_code={}\nvm_detonation_exit_code={}\n--- package-risk report ---\n{}\n--- vm detonation report ---\n{}",
        INTAKE_ASSESSMENT_SCHEMA,
        final_exit_code,
        redacted_scalar(workspace),
        package_ecosystem,
        args.tool,
        redacted_args,
        args.execute,
        args.ai_review,
        args.scanner_receipt.is_some(),
        verdict,
        reason_codes,
        package_risk.exit_code,
        vm_detonation.exit_code,
        package_risk.output,
        vm_detonation.output
    )
}

fn intake_package_ecosystem_for_tool(tool: &str) -> &'static str {
    match tool {
        "npm" => "npm",
        "pip" => "pypi",
        "uv" => "uv",
        _ => "auto",
    }
}

fn json_embedded_report(output: &str) -> String {
    let trimmed = output.trim();
    if trimmed.starts_with('{') && trimmed.ends_with('}') {
        trimmed.to_string()
    } else {
        json_string(trimmed)
    }
}

fn intake_assess_error(reason_code: &str, json: bool) -> String {
    if json {
        return format!(
            "{{\n  \"command\": \"whoathere intake assess\",\n  \"schema_version\": {},\n  \"status\": \"error\",\n  \"reason_code\": {},\n  \"exit_code\": {}\n}}",
            json_string(INTAKE_ASSESSMENT_SCHEMA),
            json_string(reason_code),
            ExitCode::Misuse.code()
        );
    }
    format!(
        "whoathere intake assess\nschema_version={}\nstatus=error\nreason_code={reason_code}\nfinal_exit_code={}",
        INTAKE_ASSESSMENT_SCHEMA,
        ExitCode::Misuse.code()
    )
}

struct PackageRiskAssessArgs<'a> {
    workspace: Option<&'a str>,
    ecosystem: Option<&'a str>,
    state_dir: Option<&'a str>,
    scanner_receipt: Option<&'a str>,
    ai_review: bool,
    ai_provider: Option<&'a str>,
    ai_model: Option<&'a str>,
    ai_timeout_seconds: Option<u64>,
    json: bool,
}

fn render_package_risk_assess(args: PackageRiskAssessArgs<'_>) -> String {
    let Some(workspace) = args.workspace else {
        return package_risk_error("package_risk_workspace_required", args.json);
    };
    let requested_ecosystem = match PackageRiskEcosystem::parse(args.ecosystem.unwrap_or("auto")) {
        Some(parsed) => parsed,
        None => return package_risk_error("package_risk_ecosystem_invalid", args.json),
    };
    let workspace_path = Path::new(workspace);
    if !workspace_path.is_dir() {
        return package_risk_error("package_risk_workspace_not_directory", args.json);
    }

    let config = macos_vm_config(args.state_dir, None, None);
    let memory = load_package_risk_memory(&config.state_dir);
    let subjects = discover_package_risk_subjects(workspace_path, requested_ecosystem);
    let workspace_sha256 = scanner_workspace_digest(workspace_path);
    let scanner_evidence = load_package_risk_scanner_evidence(
        args.scanner_receipt,
        &workspace_sha256,
        &config.state_dir,
    );
    let review_request = local_artifact_review_request(
        args.ai_review,
        args.ai_provider,
        args.ai_model,
        args.ai_timeout_seconds,
    );
    let artifact_review = run_local_artifact_review(
        workspace_path,
        requested_ecosystem,
        &subjects,
        review_request,
    );
    let receipt_id = package_risk_receipt_id(workspace_path, current_unix_seconds());
    let assessments = subjects
        .iter()
        .map(|subject| {
            assess_package_risk_subject(subject, &memory, &scanner_evidence, &artifact_review)
        })
        .collect::<Vec<_>>();
    let all_freshness_allowed = !assessments.is_empty()
        && assessments
            .iter()
            .all(|assessment| assessment.freshness_allowed);
    let all_diff_clean_or_baseline_absent = !assessments.is_empty()
        && assessments
            .iter()
            .all(|assessment| assessment.diff_clean_or_baseline_absent);
    let overall_verdict = package_risk_overall_verdict(&assessments);
    let mut summary_reasons = package_risk_summary_reasons(&assessments);
    if assessments.is_empty() {
        summary_reasons.push("package_risk_no_supported_subjects".to_string());
    }

    let receipt_path = package_risk_receipt_path(&config.state_dir, &receipt_id);
    let receipt_write_status = write_package_risk_receipt(PackageRiskReceiptWrite {
        state_dir: &config.state_dir,
        path: &receipt_path,
        receipt_id: &receipt_id,
        workspace_sha256: &workspace_sha256,
        requested_ecosystem,
        assessments: &assessments,
        scanner_evidence: &scanner_evidence,
        artifact_review: &artifact_review,
        all_freshness_allowed,
        all_diff_clean_or_baseline_absent,
        overall_verdict,
        reason_codes: &summary_reasons,
    });
    let mut store_status = "ok".to_string();
    if receipt_write_status == "ok" {
        for assessment in &assessments {
            if let Err(error) = append_package_risk_store_record(
                &config.state_dir,
                &package_risk_assessment_store_record(assessment, &receipt_id, false),
            ) {
                store_status = format!("error:{error}");
                break;
            }
        }
    }

    render_package_risk_assessment_summary(PackageRiskSummaryRender {
        requested_ecosystem,
        state_dir: &config.state_dir,
        receipt_path: &receipt_path,
        receipt_id: &receipt_id,
        workspace_sha256: &workspace_sha256,
        assessments: &assessments,
        all_freshness_allowed,
        all_diff_clean_or_baseline_absent,
        overall_verdict,
        reason_codes: &summary_reasons,
        receipt_write_status: &receipt_write_status,
        store_status: &store_status,
        scanner_evidence: &scanner_evidence,
        artifact_review: &artifact_review,
        json: args.json,
    })
}

fn render_package_risk_history(
    package: Option<&str>,
    ecosystem: Option<&str>,
    state_dir: Option<&str>,
    json: bool,
) -> String {
    let Some(package) = package else {
        return package_risk_error("package_risk_package_required", json);
    };
    let ecosystem = match PackageRiskEcosystem::parse(ecosystem.unwrap_or("auto")) {
        Some(PackageRiskEcosystem::Auto) | None => {
            return package_risk_error("package_risk_history_ecosystem_required", json)
        }
        Some(parsed) => parsed,
    };
    let config = macos_vm_config(state_dir, None, None);
    let records = load_package_risk_memory(&config.state_dir)
        .into_iter()
        .filter(|record| record.ecosystem == ecosystem && record.package_name == package)
        .collect::<Vec<_>>();
    let exit_code = ExitCode::Allow.code();
    if json {
        let records_json = records
            .iter()
            .map(render_package_risk_memory_record_json)
            .collect::<Vec<_>>()
            .join(", ");
        return format!(
            "{{\n  \"command\": \"whoathere package-risk history\",\n  \"schema_version\": {},\n  \"package\": {},\n  \"ecosystem\": {},\n  \"store_path\": {},\n  \"record_count\": {},\n  \"records\": [{}],\n  \"exit_code\": {}\n}}",
            json_string(PACKAGE_RISK_STORE_SCHEMA),
            json_string(package),
            json_string(ecosystem.as_str()),
            json_string(&redacted_package_risk_path(&package_risk_store_path(&config.state_dir))),
            records.len(),
            records_json,
            exit_code
        );
    }
    let rows = records
        .iter()
        .map(render_package_risk_memory_record_text)
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere package-risk history\nschema_version={}\npackage={}\necosystem={}\nstore_path={}\nrecord_count={}\n{}\nexit_code={}",
        PACKAGE_RISK_STORE_SCHEMA,
        package,
        ecosystem.as_str(),
        redacted_package_risk_path(&package_risk_store_path(&config.state_dir)),
        records.len(),
        rows,
        exit_code
    )
}

fn render_package_risk_approve(
    receipt: Option<&str>,
    reason: Option<&str>,
    state_dir: Option<&str>,
    json: bool,
) -> String {
    let Some(receipt) = receipt else {
        return package_risk_error("package_risk_receipt_required", json);
    };
    let Some(reason) = reason.filter(|value| !value.trim().is_empty()) else {
        return package_risk_error("package_risk_approval_reason_required", json);
    };
    let receipt_path = Path::new(receipt);
    let contents = match std::fs::read_to_string(receipt_path) {
        Ok(contents) => contents,
        Err(_) => return package_risk_error("package_risk_receipt_unreadable", json),
    };
    let config = macos_vm_config(state_dir, None, None);
    if json_extract_string_field(&contents, "schema_version").as_deref()
        != Some(PACKAGE_RISK_ASSESSMENT_SCHEMA)
    {
        return package_risk_error("package_risk_receipt_schema_invalid", json);
    }
    let auth_reasons =
        verify_package_risk_receipt_auth(Some(&config.state_dir), receipt_path, &contents);
    if !auth_reasons.is_empty() {
        return package_risk_error("package_risk_receipt_auth_invalid", json);
    }
    if json_extract_string_field(&contents, "overall_verdict").as_deref()
        != Some(PackageRiskVerdict::AutoSyncCandidate.as_str())
    {
        return package_risk_error("package_risk_approve_non_auto_sync_receipt_refused", json);
    }
    if json_extract_bool_field(&contents, "all_freshness_allowed") != Some(true)
        || json_extract_bool_field(&contents, "all_diff_clean_or_baseline_absent") != Some(true)
        || json_extract_bool_field(&contents, "all_scanner_clean") != Some(true)
        || json_extract_object_field(&contents, "scanner_evidence")
            .as_deref()
            .and_then(|object| json_extract_bool_field(object, "applied"))
            != Some(true)
        || json_extract_object_field(&contents, "scanner_evidence")
            .as_deref()
            .and_then(|object| json_extract_string_field(object, "status"))
            .as_deref()
            != Some("clean")
    {
        return package_risk_error("package_risk_approve_incomplete_evidence_refused", json);
    }
    let package_objects = json_extract_object_array(&contents, "packages");
    if package_objects.is_empty() {
        return package_risk_error("package_risk_receipt_has_no_packages", json);
    }
    let receipt_id = json_extract_string_field(&contents, "receipt_id")
        .unwrap_or_else(|| package_risk_receipt_id(receipt_path, current_unix_seconds()));
    let mut approved_records = Vec::new();
    for object in package_objects {
        let Some(record) = package_risk_approval_record_from_receipt_object(
            &object,
            &receipt_id,
            reason,
            current_unix_seconds(),
        ) else {
            return package_risk_error("package_risk_receipt_package_invalid", json);
        };
        if !package_risk_record_is_approvable_lkg(&record) {
            return package_risk_error("package_risk_approve_non_auto_sync_receipt_refused", json);
        }
        approved_records.push(record);
    }
    for record in &approved_records {
        if append_package_risk_store_record(&config.state_dir, record).is_err() {
            return package_risk_error("package_risk_store_append_failed", json);
        }
    }
    if json {
        return format!(
            "{{\n  \"command\": \"whoathere package-risk approve\",\n  \"schema_version\": {},\n  \"receipt\": {},\n  \"approved_count\": {},\n  \"approval_reason_sha256\": {},\n  \"store_path\": {},\n  \"exit_code\": 0\n}}",
            json_string(PACKAGE_RISK_STORE_SCHEMA),
            json_string(&redacted_package_risk_path(receipt_path)),
            approved_records.len(),
            json_string(&sha256_digest(reason.as_bytes())),
            json_string(&redacted_package_risk_path(&package_risk_store_path(&config.state_dir)))
        );
    }
    format!(
        "whoathere package-risk approve\nschema_version={}\nreceipt={}\napproved_count={}\napproval_reason_sha256={}\nstore_path={}\nexit_code=0",
        PACKAGE_RISK_STORE_SCHEMA,
        redacted_package_risk_path(receipt_path),
        approved_records.len(),
        sha256_digest(reason.as_bytes()),
        redacted_package_risk_path(&package_risk_store_path(&config.state_dir))
    )
}

fn package_risk_error(reason_code: &str, json: bool) -> String {
    if json {
        return format!(
            "{{\n  \"command\": \"whoathere package-risk\",\n  \"schema_version\": {},\n  \"status\": \"error\",\n  \"reason_code\": {},\n  \"exit_code\": {}\n}}",
            json_string(PACKAGE_RISK_ASSESSMENT_SCHEMA),
            json_string(reason_code),
            ExitCode::Misuse.code()
        );
    }
    format!(
        "whoathere package-risk\nschema_version={}\nstatus=error\nreason_code={reason_code}\nexit_code={}",
        PACKAGE_RISK_ASSESSMENT_SCHEMA,
        ExitCode::Misuse.code()
    )
}

struct PackageRiskSummaryRender<'a> {
    requested_ecosystem: PackageRiskEcosystem,
    state_dir: &'a Path,
    receipt_path: &'a Path,
    receipt_id: &'a str,
    workspace_sha256: &'a str,
    assessments: &'a [PackageRiskAssessment],
    all_freshness_allowed: bool,
    all_diff_clean_or_baseline_absent: bool,
    overall_verdict: PackageRiskVerdict,
    reason_codes: &'a [String],
    receipt_write_status: &'a str,
    store_status: &'a str,
    scanner_evidence: &'a PackageRiskScannerEvidence,
    artifact_review: &'a LocalArtifactReviewEvidence,
    json: bool,
}

fn render_package_risk_assessment_summary(view: PackageRiskSummaryRender<'_>) -> String {
    let exit_code = view.overall_verdict.exit_code();
    let decision_summary = package_risk_decision_summary(view.overall_verdict, view.assessments);
    let host_effect = package_risk_host_effect();
    let recommended_actions =
        package_risk_recommended_actions(view.overall_verdict, view.reason_codes);
    if view.json {
        let packages_json = view
            .assessments
            .iter()
            .map(render_package_risk_package_json)
            .collect::<Vec<_>>()
            .join(", ");
        return format!(
            "{{\n  \"command\": \"whoathere package-risk assess\",\n  \"schema_version\": {},\n  \"requested_ecosystem\": {},\n  \"workspace_sha256\": {},\n  \"cooldown_days\": {},\n  \"store_path\": {},\n  \"receipt_path\": {},\n  \"receipt_id\": {},\n  \"receipt_write_status\": {},\n  \"store_status\": {},\n  \"package_count\": {},\n  \"overall_verdict\": {},\n  \"decision_summary\": {},\n  \"host_effect\": {},\n  \"recommended_actions\": {},\n  \"all_freshness_allowed\": {},\n  \"all_diff_clean_or_baseline_absent\": {},\n  \"all_scanner_clean\": {},\n  \"scanner_evidence\": {},\n  \"artifact_review\": {},\n  \"reason_codes\": {},\n  \"packages\": [{}],\n  \"exit_code\": {}\n}}",
            json_string(PACKAGE_RISK_ASSESSMENT_SCHEMA),
            json_string(view.requested_ecosystem.as_str()),
            json_string(view.workspace_sha256),
            PACKAGE_RISK_COOLDOWN_DAYS,
            json_string(&redacted_package_risk_path(&package_risk_store_path(view.state_dir))),
            json_string(&redacted_package_risk_path(view.receipt_path)),
            json_string(view.receipt_id),
            json_string(view.receipt_write_status),
            json_string(view.store_status),
            view.assessments.len(),
            json_string(view.overall_verdict.as_str()),
            json_string(&decision_summary),
            json_string(host_effect),
            json_string_array(&recommended_actions),
            view.all_freshness_allowed,
            view.all_diff_clean_or_baseline_absent,
            view.scanner_evidence.clean_for_auto_sync(),
            render_package_risk_scanner_evidence_json(view.scanner_evidence),
            render_local_artifact_review_json(view.artifact_review),
            json_string_array(view.reason_codes),
            packages_json,
            exit_code
        );
    }
    let rows = view
        .assessments
        .iter()
        .map(render_package_risk_package_text)
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "whoathere package-risk assess\nschema_version={}\nrequested_ecosystem={}\nworkspace_sha256={}\ncooldown_days={}\nstore_path={}\nreceipt_path={}\nreceipt_id={}\nreceipt_write_status={}\nstore_status={}\npackage_count={}\noverall_verdict={}\ndecision_summary={}\nhost_effect={}\nrecommended_actions={:?}\nall_freshness_allowed={}\nall_diff_clean_or_baseline_absent={}\nall_scanner_clean={}\n{}\n{}\nreason_codes={:?}\n{}\nexit_code={}",
        PACKAGE_RISK_ASSESSMENT_SCHEMA,
        view.requested_ecosystem.as_str(),
        view.workspace_sha256,
        PACKAGE_RISK_COOLDOWN_DAYS,
        redacted_package_risk_path(&package_risk_store_path(view.state_dir)),
        redacted_package_risk_path(view.receipt_path),
        view.receipt_id,
        view.receipt_write_status,
        view.store_status,
        view.assessments.len(),
        view.overall_verdict.as_str(),
        decision_summary,
        host_effect,
        recommended_actions,
        view.all_freshness_allowed,
        view.all_diff_clean_or_baseline_absent,
        view.scanner_evidence.clean_for_auto_sync(),
        render_package_risk_scanner_evidence_text(view.scanner_evidence),
        render_local_artifact_review_text(view.artifact_review),
        view.reason_codes,
        rows,
        exit_code
    )
}

fn package_risk_decision_summary(
    verdict: PackageRiskVerdict,
    assessments: &[PackageRiskAssessment],
) -> String {
    if assessments.is_empty() {
        return "No supported npm, pip, or uv package inputs were found. Nothing was approved."
            .to_string();
    }
    let package_count = assessments.len();
    match verdict {
        PackageRiskVerdict::AutoSyncCandidate => format!(
            "{package_count} package input(s) have complete clean beta evidence and may be used as a sync-back candidate."
        ),
        PackageRiskVerdict::ManualReview => format!(
            "{package_count} package input(s) need manual review before any beta sync-back. Package code was not run on the host by this assessment."
        ),
        PackageRiskVerdict::Deny => format!(
            "{package_count} package input(s) are denied for the macOS beta. Package code was not run on the host by this assessment."
        ),
    }
}

fn package_risk_host_effect() -> &'static str {
    "assessment_only_no_package_code_executed_no_project_files_copied_receipt_and_local_memory_may_be_written"
}

fn package_risk_recommended_actions(
    verdict: PackageRiskVerdict,
    reason_codes: &[String],
) -> Vec<String> {
    let mut actions = Vec::new();
    if reason_codes
        .iter()
        .any(|reason| reason == "scanner_receipt_not_requested")
    {
        actions.push(
            "Run whoathere scanners run --execute --json for this workspace, then reassess with --scanner-receipt.".to_string(),
        );
    }
    if reason_codes
        .iter()
        .any(|reason| reason == "scanner_receipt_not_clean")
    {
        actions.push(
            "Review scanner findings and keep any package execution inside the VM until findings are resolved."
                .to_string(),
        );
    }
    if reason_codes
        .iter()
        .any(|reason| reason == "scanner_receipt_workspace_digest_mismatch")
    {
        actions.push(
            "Regenerate scanner evidence for the exact workspace being assessed.".to_string(),
        );
    }
    if reason_codes
        .iter()
        .any(|reason| reason == "unpinned_no_last_known_good")
    {
        actions.push(
            "Pin the dependency or first approve a clean last-known-good version for this package."
                .to_string(),
        );
    }
    if reason_codes
        .iter()
        .any(|reason| reason == "last_known_good_substitution_selected")
    {
        actions.push(
            "Use the selected last-known-good version instead of silently upgrading the unpinned request."
                .to_string(),
        );
    }
    if reason_codes
        .iter()
        .any(|reason| reason == "fresh_release_cooldown_active")
    {
        actions.push(
            "Wait for the fresh-release cooldown or perform manual review; the beta will not auto-sync this version yet."
                .to_string(),
        );
    }
    if reason_codes.iter().any(|reason| {
        reason == "direct_vcs_editable_denied_by_default"
            || reason.contains("dependency_source_direct_url")
            || reason.contains("dependency_source_vcs")
            || reason.contains("dependency_source_editable")
            || reason.contains("dependency_source_local")
    }) {
        actions.push(
            "Replace direct, VCS, editable, or local dependencies with pinned registry artifacts for beta auto-sync."
                .to_string(),
        );
    }
    if reason_codes.iter().any(|reason| {
        reason == "native_extension_requires_manual_review"
            || reason == "binary_wheel_requires_manual_review"
            || reason == "pypi_sdist_or_pep517_requires_manual_review"
    }) {
        actions.push(
            "Treat native, binary, and build-backend artifacts as manual review; the macOS beta does not auto-sync them."
                .to_string(),
        );
    }
    if reason_codes.iter().any(|reason| {
        reason.contains("lifecycle")
            || reason.contains("credential")
            || reason.contains("network")
            || reason.contains("pth")
            || reason.contains("platform_specific")
            || reason.contains("delayed_ci")
    }) {
        actions.push(
            "Inspect the suspicious behavior and keep execution inside the VM; do not copy outputs to the host automatically."
                .to_string(),
        );
    }
    if verdict == PackageRiskVerdict::AutoSyncCandidate {
        actions.push(
            "Use this receipt with whoathere vm release-plan or whoathere vm detonate --sync-back, then approve it as a local baseline if reviewed."
                .to_string(),
        );
    } else if actions.is_empty() {
        actions.push(
            "Review the reason_codes and keep the package out of host execution until clean evidence exists."
                .to_string(),
        );
    }
    actions.sort();
    actions.dedup();
    actions
}

