    fn temp_root(prefix: &str) -> std::path::PathBuf {
        let root = std::env::temp_dir().join(format!("{prefix}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).expect("create temp root");
        root
    }

    fn single_package_risk_receipt(state_dir: &std::path::Path) -> std::path::PathBuf {
        let receipts_dir = state_dir.join("package-risk").join("receipts");
        let mut receipts = std::fs::read_dir(&receipts_dir)
            .expect("receipts dir")
            .flatten()
            .map(|entry| entry.path())
            .filter(|path| path.extension().and_then(|ext| ext.to_str()) == Some("json"))
            .collect::<Vec<_>>();
        receipts.sort();
        assert_eq!(receipts.len(), 1);
        receipts.remove(0)
    }

    fn write_clean_package_risk_receipt(
        state_dir: &std::path::Path,
        receipt_id: &str,
        package_class: &str,
        workspace: &std::path::Path,
    ) -> std::path::PathBuf {
        let path = package_risk_receipt_path(state_dir, receipt_id);
        let unsigned = format!(
            "{{\n  \"schema_version\": {},\n  \"receipt_id\": {},\n  \"workspace_sha256\": {},\n  \"created_at_unix_seconds\": {},\n  \"requested_ecosystem\": \"pypi\",\n  \"cooldown_days\": {},\n  \"overall_verdict\": \"auto_sync_candidate\",\n  \"all_freshness_allowed\": true,\n  \"all_diff_clean_or_baseline_absent\": true,\n  \"all_scanner_clean\": true,\n  \"scanner_evidence\": {{\"requested\": true, \"applied\": true, \"scanner_clean\": true, \"status\": \"clean\", \"reason_codes\": []}},\n  \"artifact_review\": {{\"requested\": false, \"status\": \"not_requested\", \"reason_codes\": []}},\n  \"reason_codes\": [],\n  \"packages\": [{{\"subject_kind\": \"workspace\", \"ecosystem\": \"pypi\", \"package_name\": \"test-clean\", \"requested_spec\": \".\", \"resolved_version\": \"0.0.1\", \"selected_version\": \"0.0.1\", \"source_kind\": \"registry\", \"package_class\": {}, \"workspace_subject_fingerprint\": \"sha256:1111111111111111111111111111111111111111111111111111111111111111\", \"pinned\": true, \"last_known_good_version\": null, \"last_known_good_subject_fingerprint\": null, \"last_known_good_used\": false, \"publish_age_days\": 365, \"freshness_allowed\": true, \"diff_clean_or_baseline_absent\": true, \"reputation_status\": \"ok\", \"scanner_evidence_status\": \"clean\", \"scanner_clean\": true, \"scanner_evidence_reason_codes\": [], \"artifact_review_status\": \"not_requested\", \"artifact_review_reason_codes\": [], \"artifact_review_output_sha256\": null, \"indicators\": [], \"verdict\": \"auto_sync_candidate\", \"reason_codes\": []}}]\n}}\n",
            json_string(PACKAGE_RISK_ASSESSMENT_SCHEMA),
            json_string(receipt_id),
            json_string(&scanner_workspace_digest(workspace)),
            current_unix_seconds(),
            PACKAGE_RISK_COOLDOWN_DAYS,
            json_string(package_class)
        );
        let contents = sign_package_risk_receipt_contents(state_dir, &unsigned)
            .expect("signed package risk receipt");
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).expect("package risk receipt dir");
        }
        std::fs::write(&path, contents).expect("package risk receipt");
        path
    }

    fn write_scanner_run_receipt(
        path: &std::path::Path,
        state_dir: Option<&std::path::Path>,
        workspace: &std::path::Path,
        scanner_clean: bool,
        reasons: &[&str],
    ) {
        let reasons_json = reasons
            .iter()
            .map(|reason| json_string(reason))
            .collect::<Vec<_>>()
            .join(", ");
        let workspace_sha256 = scanner_workspace_digest(workspace);
        let unsigned = format!(
            "{{\"schema_version\": {}, \"created_at_unix_seconds\": {}, \"workspace_sha256\": {}, \"workspace_kind\": \"python\", \"requested_ecosystem\": \"pypi\", \"effective_ecosystem\": \"pypi\", \"execute_requested\": true, \"timeout_seconds\": 120, \"scanner_clean\": {}, \"core_scanner_count\": 5, \"core_scanner_runnable_count\": 5, \"reason_codes\": [{}], \"records\": [{{\"scanner\": \"guarddog\", \"role\": \"core\", \"status\": \"passed\", \"executable_sha256\": \"sha256:1111111111111111111111111111111111111111111111111111111111111111\"}}, {{\"scanner\": \"osv-scanner\", \"role\": \"core\", \"status\": \"passed\", \"executable_sha256\": \"sha256:2222222222222222222222222222222222222222222222222222222222222222\"}}, {{\"scanner\": \"pip-audit\", \"role\": \"core\", \"status\": \"passed\", \"executable_sha256\": \"sha256:3333333333333333333333333333333333333333333333333333333333333333\"}}, {{\"scanner\": \"syft\", \"role\": \"core\", \"status\": \"passed\", \"executable_sha256\": \"sha256:4444444444444444444444444444444444444444444444444444444444444444\"}}, {{\"scanner\": \"grype\", \"role\": \"core\", \"status\": \"passed\", \"executable_sha256\": \"sha256:5555555555555555555555555555555555555555555555555555555555555555\"}}]}}\n",
            json_string(EXTERNAL_SCANNER_RUN_SCHEMA),
            current_unix_seconds(),
            json_string(&workspace_sha256),
            scanner_clean,
            reasons_json
        );
        let contents = state_dir
            .and_then(|state_dir| sign_scanner_receipt_contents(state_dir, &unsigned).ok())
            .unwrap_or(unsigned);
        write_new_file(path, contents.as_bytes()).expect("scanner receipt");
    }

